# ─── BIC 5-rule engine (port of bic.js getMatchingBic) ───────────────────────
def resolve_bic(buyer_bank_id, seller_bank_id, buyer_trader_id, seller_trader_id, all_bic):
    buyer_codes  = [b for b in all_bic if b["bank_id"] == buyer_bank_id]
    seller_codes = [b for b in all_bic if b["bank_id"] == seller_bank_id]

    bic_buyer = bic_seller = None

    def set_b(c):
        nonlocal bic_buyer
        if not bic_buyer: bic_buyer = c

    def set_s(c):
        nonlocal bic_seller
        if not bic_seller: bic_seller = c

    SPECIAL = {'BNPAFRPP','DEUTDEFF','DEUTGB2L','UBSWAU2SXXX'}

    def classify(codes):
        dcl, branch, special = None, [], []
        for c in codes:
            bic = c.get('markitbiccode','')
            if 'DCL' in bic:          dcl = c
            elif bic in SPECIAL:      special.append(c)
            else:                     branch.append(c)
        return dcl, branch, special

    # Rule 2 – Nomura (bank_id=3)
    NIP = {2,5,6,7,16,17,18,19,22,26}
    if buyer_bank_id == 3:
        dcl, branch, _ = classify(buyer_codes)
        c = next((x for x in branch if 'NOM' in x.get('markitbiccode','')),None) \
            if seller_bank_id in NIP else dcl
        set_b(c)
    elif seller_bank_id == 3:
        dcl, branch, _ = classify(seller_codes)
        c = next((x for x in branch if 'NOM' in x.get('markitbiccode','')),None) \
            if buyer_bank_id in NIP else dcl
        set_s(c)

    # Rule 3 – Deutsche (bank_id=25)
    DEUT_FF = {78,79}
    if buyer_bank_id == 25:
        _, _, special = classify(buyer_codes)
        pat = 'FF' if buyer_trader_id in DEUT_FF else 'GB2L'
        set_b(next((x for x in special if pat in x.get('markitbiccode','')),None))
    elif seller_bank_id == 25:
        _, _, special = classify(seller_codes)
        pat = 'FF' if seller_trader_id in DEUT_FF else 'GB2L'
        set_s(next((x for x in special if pat in x.get('markitbiccode','')),None))

    # Rule 4 – BNP(4)+UBS(14)
    if buyer_bank_id == 4 and seller_bank_id == 14:
        _, _, bs = classify(buyer_codes); _, _, ss = classify(seller_codes)
        set_b(next((x for x in bs if 'FRPP' in x.get('markitbiccode','')),None))
        set_s(next((x for x in ss if 'SXXX' in x.get('markitbiccode','')),None))
    elif seller_bank_id == 4 and buyer_bank_id == 14:
        _, _, bs = classify(buyer_codes); _, _, ss = classify(seller_codes)
        set_b(next((x for x in bs if 'SXXX' in x.get('markitbiccode','')),None))
        set_s(next((x for x in ss if 'FRPP' in x.get('markitbiccode','')),None))

    # Rule 5 – Default DCL → Branch[0]
    dcl, branch, _ = classify(buyer_codes);  set_b(dcl or (branch[0] if branch else None))
    dcl, branch, _ = classify(seller_codes); set_s(dcl or (branch[0] if branch else None))

    return bic_buyer, bic_seller

# ─── Citycom/FIXEdge JSON builder ────────────────────────────────────────────
def build_mw_json(t):
    """
    Builds JSON per Citycom swaption spec (trade_example_swaption.json)
    payer/receiver refer to the UNDERLYING SWAP fixed leg direction.
    """
    sfx = "_AU"
    b_code = t["buyer_ov_bank_id"]
    s_code = t["seller_ov_bank_id"]

    if t["option_type"] == "Payers":
        payer, receiver = f"{b_code}{sfx}", f"{s_code}{sfx}"
    elif t["option_type"] == "Receivers":
        payer, receiver = f"{s_code}{sfx}", f"{b_code}{sfx}"
    else:  # Straddle
        payer, receiver = f"{b_code}{sfx}", f"{s_code}{sfx}"

    basis = 0.25 if t["swap_term_y"] <= 3 else 0.5

    payload = {
        "event":       "option",
        "type":        "outright",
        "option_type": "swaption",
        "timestamp":   t["timestamp"],
        "leg1": {
            "payer":         payer,
            "receiver":      receiver,
            "volume":        t["notional"],
            "strike":        round(t["strike_rate"] / 100, 8),
            "premium":       t["premium_bp"],
            "tenor":         t["swap_term_y"],
            "option_expiry": t["option_expiry_y"],
            "basis":         basis,
            "currency":      t["currency"],
        }
    }
    if t["option_type"] == "Straddle":
        payload["leg1"]["straddle"] = True

    return payload

# ─── Save to Supabase ─────────────────────────────────────────────────────────
def save_to_supabase(t, mw_json):
    sb = get_supabase()
    if not sb:
        return False, "Supabase not configured"
    record = {
        "trade_id":        t["trade_id"],
        "timestamp":       t["timestamp"],
        "currency":        t["currency"],
        "option_type":     t["option_type"],
        "option_expiry":   t["option_expiry"],
        "swap_term":       t["swap_term"],
        "strike_rate":     t["strike_rate"],
        "premium_bp":      t["premium_bp"],
        "notional":        t["notional"],
        "expiry_date":     t["expiry_date"],
        "swap_start_date": t["swap_start_date"],
        "premium_date":    str(t["premium_date"]),
        "settlement":      t["settlement"],
        "spot_or_fwd":     t["spot_or_fwd"],
        "clearhouse":      t.get("clearhouse",""),
        "sef":             t.get("sef", False),
        "buyer_bank":      t["buyer_bank_name"],
        "buyer_trader":    t["buyer_trader_name"],
        "seller_bank":     t["seller_bank_name"],
        "seller_trader":   t["seller_trader_name"],
        "buyer_brokerage": t.get("buyer_brokerage"),
        "seller_brokerage":t.get("seller_brokerage"),
        "bic_buyer":       t.get("bic_buyer",""),
        "bic_seller":      t.get("bic_seller",""),
        "mw_payload":      json.dumps(mw_json),
        "mw_status":       "Pending",
        "source":          "pricer",
    }
    try:
        sb.table("swaption_orders").insert(record).execute()
        return True, None
    except Exception as e:
        return False, str(e)

# ─── Main ─────────────────────────────────────────────────────────────────────
def render_ticket_tab(ss):
    st.subheader("📋 Swaption Trade Ticket → MarkitWire")

    # Load data
    all_banks     = load_banks()
    all_traders   = load_traders()
    all_divisions = load_divisions()
    all_bic       = load_bic()

    if not all_banks:
        st.error("No counterparty data. Populate re_banks / re_traders / re_bank_divisions / re_bic in Supabase.")
        return

    # Pull from pricer session state
    option_type_pre = getattr(ss, "ticket_option_type",     "Straddle")
    option_expiry   = getattr(ss, "ticket_option_expiry",   "—")
    option_expiry_y = getattr(ss, "ticket_option_expiry_y",  0.0)
    swap_term       = getattr(ss, "ticket_swap_term",        "—")
    swap_term_y     = getattr(ss, "ticket_swap_term_y",       0.0)
    expiry_date     = getattr(ss, "ticket_expiry_date",      "")
    swap_start      = getattr(ss, "ticket_swap_start_date",  "")
    strike_rate     = getattr(ss, "ticket_strike_rate",       0.0)
    premium_bp      = getattr(ss, "ticket_premium_bp",        0.0)
    notional        = getattr(ss, "ticket_notional",          100)
    currency        = getattr(ss, "ticket_currency",          "AUD")
    pricing_ok      = bool(expiry_date and swap_start and premium_bp)

    # ── Pricing (editable) ────────────────────────────────────────────────────
    st.markdown("#### Pricing")
    if not pricing_ok:
        st.warning("Run the pricer to populate pricing fields.")

    def _next_bd(d):
        d = d + timedelta(days=1)
        while d.weekday() >= 5:
            d += timedelta(days=1)
        return d

    def _add_months(d, m):
        import calendar
        yr  = d.year + (d.month - 1 + m) // 12
        mo  = (d.month - 1 + m) % 12 + 1
        day = min(d.day, calendar.monthrange(yr, mo)[1])
        return d.replace(year=yr, month=mo, day=day)

    # Versioned key so widgets reset when new ticket data arrives from blotter
    _tix_ver = f"{option_expiry}_{swap_term}_{strike_rate:.4f}"

    p1, p2, p3, p4 = st.columns(4)

    with p1:
        st.markdown(f"<p style='font-size:12px;color:#94a3b8;margin:0 0 4px 0'>Option Expiry: <b style='color:#e2e8f0'>{option_expiry}</b></p>", unsafe_allow_html=True)
        try:
            _exp_def = datetime.strptime(expiry_date, "%Y-%m-%d").date() if expiry_date else date.today()
        except:
            _exp_def = date.today()
        expiry_date_inp = st.date_input("Expiry Date", value=_exp_def,
            format="DD/MM/YYYY", key=f"tix_expiry_{_tix_ver}")
        expiry_date = expiry_date_inp.strftime("%Y-%m-%d")
        # Swap end directly under expiry in same column
        swap_end_d = _add_months(_next_bd(expiry_date_inp), int(round(max(swap_term_y, 0.25) * 12)))
        st.date_input("Swap End", value=swap_end_d, format="DD/MM/YYYY",
            key=f"tix_swap_end_{_tix_ver}", disabled=True)

    with p2:
        st.markdown(f"<p style='font-size:12px;color:#94a3b8;margin:0 0 4px 0'>Swap Term: <b style='color:#e2e8f0'>{swap_term}</b></p>", unsafe_allow_html=True)
        _start_def = _next_bd(expiry_date_inp)
        try:
            _ps = datetime.strptime(swap_start, "%Y-%m-%d").date() if swap_start else _start_def
            if _ps <= expiry_date_inp:
                _ps = _start_def
        except:
            _ps = _start_def
        swap_start_inp = st.date_input("Swap Start", value=_ps, format="DD/MM/YYYY",
            key=f"tix_swap_start_{_tix_ver}", help="Expiry +1 business day (mod following)")
        swap_start = swap_start_inp.strftime("%Y-%m-%d")
        # Rolls
        _freq_m = 3 if swap_term_y <= 3 else 6
        _rolls = [_add_months(swap_start_inp, _freq_m * (i+1)) for i in range(4)]
        _roll_str = "  ·  ".join(f"{r.day} {r.strftime('%b')}" for r in _rolls) + "…"
        st.markdown(f"<p style='font-size:12px;color:#94a3b8;margin-top:8px'>Rolls: {_roll_str}</p>", unsafe_allow_html=True)

    with p3:
        st.markdown(f"<p style='font-size:12px;color:#94a3b8;margin:0 0 4px 0'>Strike: <b style='color:#e2e8f0'>{strike_rate:.4f}%</b></p>", unsafe_allow_html=True)
        premium_bp = st.number_input("Premium (bp)", value=float(premium_bp) if premium_bp else 0.0,
            min_value=-9999.0, step=0.5, format="%.2f", key=f"tix_prem_{_tix_ver}")
        _notional_now = float(notional) if notional else 100.0
        premium_usd = _notional_now * 1_000_000 * premium_bp / 10_000
        st.metric("Premium $", f"{currency} {premium_usd:,.0f}")

    with p4:
        st.markdown(f"<p style='font-size:12px;color:#94a3b8;margin:0 0 4px 0'>Convention: <b style='color:#e2e8f0'>{'QQ (3M)' if swap_term_y <= 3 else 'SS (6M)'}</b></p>", unsafe_allow_html=True)
        notional = st.number_input("Notional (MM)", value=float(notional) if notional else 100.0,
            min_value=1.0, step=25.0, format="%.0f", key=f"tix_notional_{_tix_ver}")

    pricing_ok = bool(expiry_date and swap_start and premium_bp)
    st.divider()

    # ── Trade details ─────────────────────────────────────────────────────────
    st.markdown("#### Trade Details")
    d1,d2,d3 = st.columns(3)
    with d1:
        option_type = st.selectbox("Option Type",
            ["Straddle","Payers","Receivers"],
            index=["Straddle","Payers","Receivers"].index(option_type_pre)
                  if option_type_pre in ["Straddle","Payers","Receivers"] else 0)
        settlement = st.selectbox("Settlement", ["Physical","Swap"], index=0,
            help="Physical → LCH Cleared Swap (AUD standard)")
    with d2:
        spot_or_fwd = st.selectbox("Premium Basis", ["Fwd","Spot"],
            help="Fwd = forward premium (AFMA s3.13)")
        clearhouse  = st.selectbox("Clearhouse", ["LCH","CME","Bilateral"])
    with d3:
        sef = st.checkbox("SEF", value=False)
        prem_auto = expiry_date_inp if settlement == "Physical" else expiry_date_inp + timedelta(days=1)
        premium_date = st.date_input("Premium Date", value=prem_auto,
            help="Auto: expiry (Physical) or T+1 (Cash). AFMA s3.11.3")

    st.divider()

    # ── Counterparties ────────────────────────────────────────────────────────
    st.markdown("#### Counterparties")
    bank_map   = {b["bank"]: b for b in all_banks}
    bank_names = sorted(bank_map.keys())

    def t_for(bank_id): return [t for t in all_traders   if t["bank_id"] == bank_id]
    def d_for(bank_id): return [d for d in all_divisions if d["bank_id"] == bank_id]

    col_b, col_s = st.columns(2)

    with col_b:
        st.markdown("**Buyer** *(premium payer)*")
        bb_name = st.selectbox("Bank",   bank_names, key="bb")
        bb      = bank_map[bb_name]
        bt_map  = {f"{t['firstname']} {t['lastname']}": t for t in t_for(bb["bank_id"])}
        bt_name = st.selectbox("Trader", sorted(bt_map) or ["—"], key="bt")
        bt      = bt_map.get(bt_name)
        bd_list = d_for(bb["bank_id"])
        if bd_list:
            bd_map  = {d["name"]: d for d in bd_list}
            bd_name = st.selectbox("Division", sorted(bd_map), key="bd")
        else:
            st.caption("No division records — BIC used directly")
        b_brok = st.number_input("Brokerage (AUD)", 0.0, value=500.0, step=50.0, key="b_brok")

    with col_s:
        st.markdown("**Seller** *(premium receiver)*")
        sb_name = st.selectbox("Bank",   bank_names, key="sb")
        sb_     = bank_map[sb_name]
        st_map  = {f"{t['firstname']} {t['lastname']}": t for t in t_for(sb_["bank_id"])}
        st_name = st.selectbox("Trader", sorted(st_map) or ["—"], key="st_")
        st_     = st_map.get(st_name)
        sd_list = d_for(sb_["bank_id"])
        if sd_list:
            sd_map  = {d["name"]: d for d in sd_list}
            sd_name = st.selectbox("Division", sorted(sd_map), key="sd")
        else:
            st.caption("No division records — BIC used directly")
        s_brok = st.number_input("Brokerage (AUD)", 0.0, value=500.0, step=50.0, key="s_brok")

    buyer_ok  = bool(bt)
    seller_ok = bool(st_)

    # BIC auto-resolve
    bic_b_code = bic_s_code = ""
    if buyer_ok and seller_ok:
        bic_b, bic_s = resolve_bic(
            bb["bank_id"], sb_["bank_id"],
            bt["trader_id"], st_["trader_id"],
            all_bic
        )
        bic_b_code = bic_b["markitbiccode"] if bic_b else "⚠️ Not found"
        bic_s_code = bic_s["markitbiccode"] if bic_s else "⚠️ Not found"
        st.divider()
        bc1, bc2 = st.columns(2)
        bc1.metric("BIC Buyer",  bic_b_code)
        bc2.metric("BIC Seller", bic_s_code)

    st.divider()

    # ── Generate ──────────────────────────────────────────────────────────────
    can_go = pricing_ok and buyer_ok and seller_ok

    if st.button("📄 Generate Ticket", type="primary",
                 disabled=not can_go, use_container_width=True):

        trade_id = f"SWN{datetime.utcnow().strftime('%Y%m%d%H%M%S')}-{swap_term}-{option_expiry}"

        ticket = {
            "trade_id":          trade_id,
            "timestamp":         datetime.utcnow().isoformat() + "Z",
            "currency":          currency,
            "option_type":       option_type,
            "option_expiry":     option_expiry,
            "option_expiry_y":   option_expiry_y,
            "swap_term":         swap_term,
            "swap_term_y":       swap_term_y,
            "expiry_date":       expiry_date,
            "swap_start_date":   swap_start,
            "premium_date":      premium_date,
            "strike_rate":       strike_rate,
            "premium_bp":        premium_bp,
            "notional":          notional,
            "settlement":        settlement,
            "spot_or_fwd":       spot_or_fwd,
            "clearhouse":        clearhouse,
            "sef":               sef,
            "buyer_bank_name":   bb_name,
            "buyer_ov_bank_id":  bb.get("short_code", bb_name),
            "buyer_trader_id":   bt["trader_id"],
            "buyer_trader_name": bt_name,
            "buyer_brokerage":   b_brok,
            "seller_bank_name":  sb_name,
            "seller_ov_bank_id": sb_.get("short_code", sb_name),
            "seller_trader_id":  st_["trader_id"],
            "seller_trader_name":st_name,
            "seller_brokerage":  s_brok,
            "bic_buyer":         bic_b_code,
            "bic_seller":        bic_s_code,
        }

        mw_json = build_mw_json(ticket)
        ok, err = save_to_supabase(ticket, mw_json)

        ss.last_ticket   = ticket
        ss.last_mw_json  = mw_json

        if ok:
            st.success(f"✅ Ticket saved — `{trade_id}`")
        else:
            st.warning(f"Supabase insert failed ({err}) — ticket shown below for manual use.")

    # ── Display ───────────────────────────────────────────────────────────────
    if hasattr(ss, "last_ticket"):
        ticket  = ss.last_ticket
        mw_json = ss.last_mw_json

        st.divider()
        st.markdown(f"#### `{ticket['trade_id']}`")

        rows = {
            "Option Type":      ticket["option_type"],
            "Expiry":           f"{ticket['option_expiry']} / {ticket['expiry_date']}",
            "Underlying":       f"{ticket['swap_term']} swap from {ticket['swap_start_date']}",
            "Strike":           f"{ticket['strike_rate']:.4f}%",
            "Premium":          f"{ticket['premium_bp']:.2f} bp ({ticket['spot_or_fwd']})",
            "Notional":         f"{ticket['currency']} {ticket['notional']}MM",
            "Settlement":       f"{ticket['settlement']} — {ticket['clearhouse']}",
            "Premium Date":     str(ticket["premium_date"]),
            "Buyer":            f"{ticket['buyer_trader_name']} [{ticket['buyer_bank_name']}]",
            "Seller":           f"{ticket['seller_trader_name']} [{ticket['seller_bank_name']}]",
            "Buyer Brokerage":  f"AUD {ticket['buyer_brokerage']:,.0f}",
            "Seller Brokerage": f"AUD {ticket['seller_brokerage']:,.0f}",
            "BIC Buyer":        ticket["bic_buyer"],
            "BIC Seller":       ticket["bic_seller"],
        }
        for k, v in rows.items():
            r1, r2 = st.columns([1,2])
            r1.markdown(f"**{k}**")
            r2.write(v)

        st.divider()
        st.markdown("#### MW JSON Payload")
        st.code(json.dumps(mw_json, indent=2), language="json")
        st.caption("Ready for FIXEdge/Citycom submission once MW credentials are loaded.")

    elif not can_go:
        missing = []
        if not pricing_ok:  missing.append("pricing (run pricer)")
        if not buyer_ok:    missing.append("buyer counterparty")
        if not seller_ok:   missing.append("seller counterparty")
        st.info("Complete: " + " · ".join(missing))

HAS_TICKET_TAB = True

SUPPORTED_CURRENCIES = ["AUD", "NZD", "USD"]
ALL_CURRENCIES = ["AUD", "NZD", "USD", "EUR (PENDING)", "GBP (PENDING)", "JPY (PENDING)", "CAD (PENDING)"]


# ============================
# Database Functions
# ============================

def get_db_url():
    """
    Get Supabase PostgreSQL connection URL from environment variable.
    Set RATEEDGE_DB_URL in .env (local) or Streamlit secrets (cloud).
    Format: postgresql://postgres.[project-ref]:[password]@aws-0-ap-southeast-2.pooler.supabase.com:5432/postgres
    """
    import os
    # 1. Try Streamlit secrets (cloud deployment)
    try:
        return st.secrets["RATEEDGE_DB_URL"]
    except Exception:
        pass
    # 2. Try environment variable (local .env)
    url = os.environ.get("RATEEDGE_DB_URL", "")
    return url if url else None

@st.cache_resource(show_spinner=False)
def _get_db_params():
    """Parse and cache DB connection params once."""
    db_url = get_db_url()
    if not db_url:
        return None
    try:
        from urllib.parse import urlparse, parse_qs
        r = urlparse(db_url)
        qs = parse_qs(r.query)
        return {
            "host": r.hostname, "port": r.port or 5432,
            "dbname": r.path.lstrip('/'), "user": r.username,
            "password": r.password,
            "sslmode": qs.get('sslmode', ['require'])[0]
        }
    except:
        return None

def get_db_connection():
    """
    Get Supabase PostgreSQL connection via shared pooler URL.
    """
    if not HAS_POSTGRES:
        return None
    params = _get_db_params()
    if not params:
        return None
    try:
        conn = psycopg2.connect(
            host=params["host"], port=params["port"],
            dbname=params["dbname"], user=params["user"],
            password=params["password"], sslmode=params["sslmode"],
            connect_timeout=10,
            keepalives=1, keepalives_idle=30,
            keepalives_interval=10, keepalives_count=3,
            options="-c statement_timeout=15000"  # 15s max per query
        )
        return conn
    except Exception:
        return None


def init_database():
    """Create tables if they don't exist"""
    conn = get_db_connection()
    if not conn:
        return False
    
    try:
        cur = conn.cursor()
        cur.execute("""
            CREATE TABLE IF NOT EXISTS user_configs (
                id SERIAL PRIMARY KEY,
                user_id VARCHAR(50) NOT NULL,
                config_type VARCHAR(50) NOT NULL,
                currency VARCHAR(3) NOT NULL,
                data JSONB NOT NULL,
                updated_at TIMESTAMP DEFAULT NOW(),
                UNIQUE(user_id, config_type, currency)
            );
            
            CREATE INDEX IF NOT EXISTS idx_user_configs_user 
            ON user_configs(user_id);
            
            CREATE TABLE IF NOT EXISTS vol_history (
                id SERIAL PRIMARY KEY,
                user_id VARCHAR(50) NOT NULL,
                currency VARCHAR(3) NOT NULL,
                snapshot_date TIMESTAMP NOT NULL,
                label VARCHAR(100) NOT NULL,
                atm_vols JSONB NOT NULL,
                atm_prems JSONB,
                sabr_alpha JSONB,
                sabr_beta JSONB,
                sabr_rho JSONB,
                sabr_nu JSONB,
                notes TEXT,
                created_at TIMESTAMP DEFAULT NOW()
            );
            
            CREATE INDEX IF NOT EXISTS idx_vol_history_user_ccy 
            ON vol_history(user_id, currency);
            
            CREATE INDEX IF NOT EXISTS idx_vol_history_date 
            ON vol_history(snapshot_date DESC);
            
            ALTER TABLE vol_history ADD COLUMN IF NOT EXISTS atm_prems JSONB;

            CREATE TABLE IF NOT EXISTS sod_reports (
                id SERIAL PRIMARY KEY,
                user_id VARCHAR(50) NOT NULL,
                report_date DATE NOT NULL,
                created_at TIMESTAMP DEFAULT NOW(),
                usd_t1_label TEXT,
                usd_t2_label TEXT,
                aud_snap_label TEXT,
                report_data JSONB,
                notes TEXT
            );

            CREATE INDEX IF NOT EXISTS idx_sod_reports_user_date
            ON sod_reports(user_id, report_date DESC);

            CREATE TABLE IF NOT EXISTS blotter_mids (
                id SERIAL PRIMARY KEY,
                ccy VARCHAR(3) NOT NULL,
                key VARCHAR(50) NOT NULL,
                value NUMERIC,
                label TEXT,
                updated_at TIMESTAMP DEFAULT NOW(),
                UNIQUE(ccy, key)
            );
            CREATE INDEX IF NOT EXISTS idx_blotter_mids_ccy ON blotter_mids(ccy, key);
        """)
        conn.commit()
        cur.close()
        conn.close()
        return True
    except Exception as e:
        st.error(f"Database init failed: {e}")
        return False


def save_user_config(user_id: str, config_type: str, currency: str, data: dict, _conn=None):
    """Save user config to database. Pass _conn to reuse an existing connection.
    
    AUD LOCK GUARD (20-Apr-2026): config types that are genuinely tied to a
    currency (cf_spreads, cfs_table_data, sabr_*, etc.) must not write to the
    AUD row when the active caps/floors tab ccy is not AUD. This prevents the
    class of bug where a USD edit overwrites AUD's stored wedges/SABR params
    because of a stale hardcoded "AUD" literal somewhere in the save path.
    Global configs (GLOBAL, GLB prefixes) and AUD-specific tools (morning
    rates, RV snap, conviction book, SPI blotter) are exempt.
    """
    # Guard: if writing to AUD row on a ccy-bound config, confirm active ccy is AUD
    _CCY_BOUND_CONFIGS = {
        "cf_spreads", "cfs_table_data", "sabr_alpha", "sabr_rho", "sabr_nu",
        "sabr_beta", "sabr_shift", "atm_surface",
    }
    if config_type in _CCY_BOUND_CONFIGS and currency == "AUD":
        try:
            import streamlit as _st_guard
            _active_cf_ccy = _st_guard.session_state.get("_cf_last_active_ccy")
            if _active_cf_ccy is not None and _active_cf_ccy != "AUD":
                # Active caps/floors tab is not AUD — silently abort this write
                # to prevent cross-ccy contamination. This is a defensive rail;
                # caller should already pass the correct ccy. Log to a session
                # list so we can surface in UI if it happens.
                _guard_log = _st_guard.session_state.setdefault("_aud_lock_blocks", [])
                _guard_log.append({
                    "config_type": config_type,
                    "attempted_ccy": currency,
                    "active_ccy":    _active_cf_ccy,
                })
                return False
        except Exception:
            pass  # If Streamlit isn't available (non-UI context), proceed
    own_conn = _conn is None
    conn = get_db_connection() if own_conn else _conn
    if not conn:
        return False
    try:
        cur = conn.cursor()
        cur.execute("""
            INSERT INTO user_configs (user_id, config_type, currency, data, updated_at)
            VALUES (%s, %s, %s, %s, NOW())
            ON CONFLICT (user_id, config_type, currency)
            DO UPDATE SET data = %s, updated_at = NOW()
        """, (user_id, config_type, currency, Json(data), Json(data)))
        if own_conn:
            conn.commit()
            cur.close()
            conn.close()
        else:
            cur.close()
        # v2104b: clear load_user_config cache so subsequent reads see
        # this write. The @st.cache_data(ttl=1800) on load_user_config
        # was holding stale values for up to 30 min, defeating the save.
        try:
            load_user_config.clear()
        except Exception:
            pass
        return True
    except Exception as e:
        if own_conn:
            try: conn.close()
            except: pass
        return False


@st.cache_data(ttl=1800, show_spinner=False)
def load_user_config(user_id: str, config_type: str, currency: str) -> Optional[dict]:
    """Load user config from database"""
    conn = get_db_connection()
    if not conn:
        return None
    
    try:
        cur = conn.cursor()
        cur.execute("""
            SELECT data FROM user_configs 
            WHERE user_id = %s AND config_type = %s AND currency = %s
        """, (user_id, config_type, currency))
        row = cur.fetchone()
        cur.close()
        conn.close()
        return row[0] if row else None
    except Exception as e:
        return None


def load_all_user_configs(user_id: str) -> dict:
    """Load all configs for a user"""
    conn = get_db_connection()
    if not conn:
        return {}
    
    try:
        cur = conn.cursor()
        cur.execute("""
            SELECT config_type, currency, data, updated_at 
            FROM user_configs 
            WHERE user_id = %s
            ORDER BY updated_at DESC
        """, (user_id,))
        rows = cur.fetchall()
        cur.close()
        conn.close()
        
        configs = {}
        for config_type, currency, data, updated_at in rows:
            if config_type not in configs:
                configs[config_type] = {}
            configs[config_type][currency] = {
                "data": data,
                "updated_at": updated_at.isoformat() if updated_at else None
            }
        return configs
    except Exception as e:
        return {}


def save_all_session_data(user_id: str):
    """Save all current session data using a single DB connection."""
    conn = get_db_connection()
    if not conn:
        return 0
    saved = 0
    try:
        def _save(config_type, currency, data):
            nonlocal saved
            cur = conn.cursor()
            cur.execute("""
                INSERT INTO user_configs (user_id, config_type, currency, data, updated_at)
                VALUES (%s, %s, %s, %s, NOW())
                ON CONFLICT (user_id, config_type, currency)
                DO UPDATE SET data = %s, updated_at = NOW()
            """, (user_id, config_type, currency, Json(data), Json(data)))
            cur.close()
            saved += 1

        _debug_msgs = []
        for ccy in SUPPORTED_CURRENCIES:
            # ATM vols are NOT saved to user_configs — they live in vol_history only
            # Saving here caused stale/wrong surfaces to override vol_history on load
            vol_data = st.session_state.get("vol_data", {}).get(ccy, {})

            for param in ["alpha", "beta", "rho", "nu"]:
                val = vol_data.get(param)
                if val is not None:
                    val_save = val.copy()
                    if val_save.index.name == "Expiry":
                        val_save = val_save.reset_index()
                    elif "Expiry" not in val_save.columns:
                        first_idx = val_save.index[0] if len(val_save) > 0 else None
                        if isinstance(first_idx, str) and first_idx.lower().endswith(('w','m','y')):
                            val_save = val_save.reset_index()
                            val_save.columns = ["Expiry"] + list(val_save.columns[1:])
                    records = []
                    for _, row in val_save.iterrows():
                        rec = {"Expiry": row.get("Expiry", "")}
                        for col in val_save.columns:
                            if col != "Expiry": rec[col] = row[col]
                        records.append(rec)
                    _save(f"sabr_{param}", ccy, {"values": records})

            basis = st.session_state.get("basis_curves", {}).get(ccy, {})
            for basis_type in ["6v3", "3v1", "ois"]:
                bc = basis.get(basis_type)
                if bc is not None:
                    bc_save = bc.copy()
                    if bc_save.index.name is not None:
                        bc_save = bc_save.reset_index()
                    _save(f"basis_{basis_type}", ccy, {"values": bc_save.to_dict(orient="records")})

        # AUD: save all 5 curves to DB so cold reload is fully self-contained
        # PAR (qq+ss), OIS zeros, bootstrapped zeros (qq/ss/qq_full), 6v3 basis, 3v1 basis
        _par_qq = st.session_state.get("_aud_par_qq", {})
        _par_ss = st.session_state.get("_aud_par_ss", {})
        if _par_qq and _par_ss:
            def _basis_df_to_dict(df):
                if df is None or df.empty: return {}
                try: return {str(float(r["MaturityY"])): float(r["BasisBp"]) for _, r in df.iterrows()}
                except Exception: return {}
            def _zc_dict_clean(d):
                if not d: return {}
                return {str(float(k)): float(v) for k, v in d.items()}
            _cb = st.session_state.get("config_basis", {}).get("AUD", {})
            _ois_zc = st.session_state.get("_aud_zc_qq", {})  # OIS seeds embedded in bootstrap
            _aud_db_payload = {
                "par_qq":     _par_qq,
                "par_ss":     _par_ss,
                "basis_6v3":  _basis_df_to_dict(_cb.get("6v3")),
                "basis_3v1":  _basis_df_to_dict(_cb.get("3v1")),
                "ois_zeros":  _basis_df_to_dict(_cb.get("ois")),
                "zc_qq":      _zc_dict_clean(st.session_state.get("_aud_zc_qq")),
                "zc_ss":      _zc_dict_clean(st.session_state.get("_aud_zc_ss")),
                "zc_qq_full": _zc_dict_clean(st.session_state.get("_aud_zc_qq_full")),
            }
            _save("aud_par_rates", "AUD", _aud_db_payload)

        # CFS spreads — save all 9 wedge spread values under whichever ccy
        # was last active in the caps_floors tab (defaults to AUD if unset).
        _cf_spread_keys = ["cf_spr_3m1y","cf_spr_1y1y","cf_spr_2y1y","cf_spr_3y1y",
                           "cf_spr_4y1y","cf_spr_5y2y","cf_spr_7y3y","cf_spr_10y2y",
                           "cf_spr_12y3y","cf_spr_15v20","cf_spr_20v30"]
        _cf_spread_data = {k: float(st.session_state.get(k, 0)) for k in _cf_spread_keys
                           if k in st.session_state}
        _cf_save_ccy = st.session_state.get("_cf_last_active_ccy", "AUD")
        if _cf_spread_data:
            _save("cf_spreads", _cf_save_ccy, _cf_spread_data)

        # CFS table data — manually entered straddle overrides per wedge
        _cfs_tdata = st.session_state.get("cfs_table_data", {})
        if _cfs_tdata:
            _save("cfs_table_data", _cf_save_ccy, _cfs_tdata)

        # FWD prefs
        _fwd_prefs = {
            "irs_sp_list":  [list(x) for x in st.session_state.get("irs_sp_list", [])],
            "irs_fl_list":  [list(x) for x in st.session_state.get("irs_fl_list", [])],
            "fvfv_list":    [list(x) for x in st.session_state.get("fvfv_list", [])],
            "b6_list":      list(st.session_state.get("b6_list", [])),
            "fv6_list":     [list(x) for x in st.session_state.get("fv6_list", [])],
            "bsp_list":     [list(x) for x in st.session_state.get("bsp_list", [])],
        }
        if any(_fwd_prefs.values()):
            _save("fwd_analysis_prefs", "GLB", _fwd_prefs)

        conn.commit()
        try:
            import streamlit as _st
            _st.session_state["_save_debug_msgs"] = _debug_msgs
        except: pass
    except Exception as _e:
        try: conn.rollback()
        except: pass
        try:
            import streamlit as _st
            _st.session_state["_save_last_error"] = str(_e)
        except: pass
    finally:
        try: conn.close()
        except: pass
    return saved


def load_all_session_data(user_id: str, load_date: str = None) -> int:
    """Load all saved data into session state. load_date: specific date string (YYYY-MM-DD) or None for latest."""
    configs = load_all_user_configs(user_id)
    # If nothing found, try the other admin email as fallback
    # (desktop may have saved as wpo@rateedge.au, phone logs in as wpo70@icloud.com or vice versa)
    if not configs:
        _ADMIN_ALIASES = {"wpo@rateedge.au": "wpo70@icloud.com", "wpo70@icloud.com": "wpo@rateedge.au"}
        _alt = _ADMIN_ALIASES.get(user_id)
        if _alt:
            configs = load_all_user_configs(_alt)
    if not configs:
        return 0
    
    loaded = 0
    
    # Initialize session state containers
    if "curves" not in st.session_state:
        st.session_state["curves"] = {}
    if "vol_data" not in st.session_state:
        st.session_state["vol_data"] = {}
    if "basis_curves" not in st.session_state:
        st.session_state["basis_curves"] = {}
    if "vol_editor" not in st.session_state:
        st.session_state["vol_editor"] = {"working": {}, "base": {}, "history": {}, "redo_stack": {}, "selected_cell": {}}
    
    for ccy in SUPPORTED_CURRENCIES:
        # Initialize vol_data for this currency
        if ccy not in st.session_state["vol_data"]:
            st.session_state["vol_data"][ccy] = {}
        
        # NOTE: Curves are NOT auto-loaded from DB on login.
        # Curves must be committed from BBG_Feed via Vol/Upload tab.
        # This ensures curves always reflect the live BBG rates, not stale DB zeros.

        # ATM vols are NOT loaded from user_configs — they come from vol_history only
        # (see auto-load block at login which pulls latest snapshot per currency)
        
        # Load SABR params into vol_data
        for param in ["alpha", "beta", "rho", "nu"]:
            key = f"sabr_{param}"
            if key in configs and ccy in configs[key]:
                try:
                    df = pd.DataFrame(configs[key][ccy]["data"]["values"])
                    # Reorder columns to ensure Expiry is first if it exists
                    if "Expiry" in df.columns:
                        cols = ["Expiry"] + [c for c in df.columns if c != "Expiry"]
                        df = df[cols]
                    st.session_state["vol_data"][ccy][param] = df
                    loaded += 1
                except:
                    pass
        
        # Load basis curves
        if ccy not in st.session_state["basis_curves"]:
            st.session_state["basis_curves"][ccy] = {}
        
        for basis_type in ["6v3", "3v1", "ois"]:
            key = f"basis_{basis_type}"
            if key in configs and ccy in configs[key]:
                try:
                    df = pd.DataFrame(configs[key][ccy]["data"]["values"])
                    st.session_state["basis_curves"][ccy][basis_type] = df
                    if "config_basis" not in st.session_state:
                        st.session_state["config_basis"] = {}
                    if ccy not in st.session_state["config_basis"]:
                        st.session_state["config_basis"][ccy] = {}
                    st.session_state["config_basis"][ccy][basis_type] = df
                    loaded += 1
                except:
                    pass

    # AUD: restore all 5 curves from DB — PAR, OIS, ZERO (qq/ss/qq_full), 6v3, 3v1
    if "aud_par_rates" in configs and "AUD" in configs["aud_par_rates"]:
        try:
            _pdata = configs["aud_par_rates"]["AUD"]["data"]
            _par_qq = {float(k): float(v) for k, v in _pdata.get("par_qq", {}).items()}
            _par_ss = {float(k): float(v) for k, v in _pdata.get("par_ss", {}).items()}
            if _par_qq and _par_ss:
                st.session_state["_aud_par_qq"] = _par_qq
                st.session_state["_aud_par_ss"] = _par_ss

                # PAR display table
                _par_rows = []
                for _t, _r in sorted(_par_qq.items()): _par_rows.append({"Tenor": f"{_t}Y", "Par Rate (%)": _r, "Conv": "Q/Q"})
                for _t, _r in sorted(_par_ss.items()): _par_rows.append({"Tenor": f"{_t}Y", "Par Rate (%)": _r, "Conv": "S/S"})
                if "_irs_par_rates" not in st.session_state: st.session_state["_irs_par_rates"] = {}
                st.session_state["_irs_par_rates"]["AUD"] = pd.DataFrame(_par_rows)

                def _db_dict_to_zc(d):
                    if not d: return {}
                    return {float(k): float(v) for k, v in d.items()}

                def _db_dict_to_basis_df(d, col="BasisBp"):
                    if not d: return None
                    rows = sorted([(float(k), float(v)) for k, v in d.items()])
                    return pd.DataFrame({"MaturityY": [r[0] for r in rows], col: [r[1] for r in rows]})

                # Restore bootstrapped zero curves directly — no re-bootstrap needed
                _zc_qq_db     = _db_dict_to_zc(_pdata.get("zc_qq", {}))
                _zc_ss_db     = _db_dict_to_zc(_pdata.get("zc_ss", {}))
                _zc_qq_full_db= _db_dict_to_zc(_pdata.get("zc_qq_full", {}))

                # Restore basis curves to config_basis and basis_curves
                _b6v3_df = _db_dict_to_basis_df(_pdata.get("basis_6v3", {}))
                _b3v1_df = _db_dict_to_basis_df(_pdata.get("basis_3v1", {}))
                _ois_df  = _db_dict_to_basis_df(_pdata.get("ois_zeros", {}), col="BasisBp")

                for _store in ["config_basis", "basis_curves"]:
                    st.session_state.setdefault(_store, {}).setdefault("AUD", {})
                if _b6v3_df is not None:
                    st.session_state["config_basis"]["AUD"]["6v3"] = _b6v3_df
                    st.session_state["basis_curves"]["AUD"]["6v3"] = _b6v3_df
                if _b3v1_df is not None:
                    st.session_state["config_basis"]["AUD"]["3v1"] = _b3v1_df
                    st.session_state["basis_curves"]["AUD"]["3v1"] = _b3v1_df
                if _ois_df is not None:
                    # OIS stored with BasisBp col = ZeroRatePct for ois entries
                    _ois_zc_df = _ois_df.rename(columns={"BasisBp": "ZeroRatePct"})
                    st.session_state["config_basis"]["AUD"]["ois"] = _ois_zc_df
                    st.session_state["basis_curves"]["AUD"]["ois"] = _ois_zc_df

                if _zc_qq_db and _zc_ss_db and _zc_qq_full_db:
                    # Fast path: zeros saved, restore directly
                    st.session_state["_aud_zc_qq"]      = _zc_qq_db
                    st.session_state["_aud_zc_ss"]      = _zc_ss_db
                    st.session_state["_aud_zc_qq_full"] = _zc_qq_full_db
                else:
                    # Legacy path: re-bootstrap from par rates + basis (old DB records)
                    _SPOT2 = 1.0 / 252.0
                    _bx2 = _by2 = None
                    if _b6v3_df is not None:
                        _bx2 = _b6v3_df["MaturityY"].to_numpy().astype(float)
                        _by2 = _b6v3_df["BasisBp"].to_numpy().astype(float)
                    def _b2(t):
                        if _bx2 is None: return 0.0
                        return float(np.interp(t, _bx2, _by2))
                    def _boot_clean2(par_dict, freq, seed_dfs=None):
                        _dfs2 = {0.0: 1.0, _SPOT2: 1.0}
                        if seed_dfs: _dfs2.update(seed_dfs)
                        def _dfi2c(t):
                            _ts2 = sorted(_dfs2.keys()); _dfv2 = [_dfs2[x] for x in _ts2]
                            if t <= _ts2[0]: return 1.0
                            if t >= _ts2[-1]:
                                _z2 = -math.log(max(_dfv2[-1],1e-10))/_ts2[-1]; return math.exp(-_z2*t)
                            return math.exp(float(np.interp(t,_ts2,np.log(np.maximum(_dfv2,1e-10)))))
                        for _T2 in sorted(par_dict):
                            _c2 = par_dict[_T2]/100.0; _te2 = _T2+_SPOT2
                            _tm2=[]; _ti2=_SPOT2+freq
                            while _ti2<=_te2+1e-9: _tm2.append(round(min(_ti2,_te2),8)); _ti2+=freq
                            if not _tm2: continue
                            _an2 = sum(_dfi2c(_ti2)*freq for _ti2 in _tm2[:-1])
                            _df2 = (1.0-_c2*_an2)/(1.0+_c2*freq)
                            if _df2>0: _dfs2[_te2]=_df2
                        _M2=[0.25,0.5,0.75,1,1.5,2,3,4,5,6,7,8,9,10,12,15,20,25,30,40,50]
                        return {_m2:-math.log(_dfi2c(_m2))/_m2*100 for _m2 in _M2 if _dfi2c(_m2)>0}, _dfs2
                    _zc_qq_db, _dfs_qq2   = _boot_clean2(_par_qq, 0.25)
                    _seed_ss2             = {_t:_d for _t,_d in _dfs_qq2.items() if _t<=3.1}
                    _zc_ss_db, _          = _boot_clean2(_par_ss, 0.5, seed_dfs=_seed_ss2)
                    _pqq_long2            = {_t:_r-_b2(_t)/100.0 for _t,_r in _par_ss.items() if _t<=30}
                    _zc_qqf2, _           = _boot_clean2(_pqq_long2, 0.25, seed_dfs={_t:_d for _t,_d in _dfs_qq2.items() if _t<=3.1})
                    _zc_qq_full_db        = {**_zc_qq_db, **{_m:_z for _m,_z in _zc_qqf2.items() if _m>=4}}
                    st.session_state["_aud_zc_qq"]      = _zc_qq_db
                    st.session_state["_aud_zc_ss"]      = _zc_ss_db
                    st.session_state["_aud_zc_qq_full"] = _zc_qq_full_db

                # Build blended proj curve: QQ<=3.25Y, SS>=3.5Y
                _rows2  = [{"MaturityY": float(_m), "ZeroRatePct": float(_z)} for _m,_z in sorted(_zc_qq_db.items()) if _m<=3.25]
                _rows2 += [{"MaturityY": float(_m), "ZeroRatePct": float(_z)} for _m,_z in sorted(_zc_ss_db.items()) if _m>=3.5]
                if len(_rows2) >= 10:
                    st.session_state["_aud_proj_curve"] = pd.DataFrame(_rows2)
                st.session_state.get("_fwd_ann_cache", {}).clear()
                loaded += 1
        except Exception as _pex:
            pass
            pass

    # Restore CFS wedge spreads
    if "cf_spreads" in configs and "AUD" in configs["cf_spreads"]:
        try:
            _cf_d = configs["cf_spreads"]["AUD"]["data"]
            for _k, _v in _cf_d.items():
                st.session_state[_k] = float(_v)
            loaded += 1
        except Exception:
            pass

    # Restore CFS table data (manually entered straddle overrides)
    if "cfs_table_data" in configs and "AUD" in configs["cfs_table_data"]:
        try:
            _ctd = configs["cfs_table_data"]["AUD"]["data"]
            if not isinstance(_ctd, dict):
                _ctd = {}
            if "cfs_table_data" not in st.session_state:
                st.session_state["cfs_table_data"] = {}
            st.session_state["cfs_table_data"].update(_ctd)
            loaded += 1
        except Exception:
            pass

    # Restore FWD Analysis series lists   —   DB always wins, overrides tab defaults
    if "fwd_analysis_prefs" in configs and "GLB" in configs["fwd_analysis_prefs"]:
        try:
            _p = configs["fwd_analysis_prefs"]["GLB"]["data"]
            if "irs_sp_list" in _p:
                st.session_state["irs_sp_list"] = [tuple(x) for x in _p["irs_sp_list"]]
            if "irs_fl_list" in _p:
                st.session_state["irs_fl_list"] = [tuple(x) for x in _p["irs_fl_list"]]
            if "fvfv_list" in _p:
                st.session_state["fvfv_list"] = [tuple(x) for x in _p["fvfv_list"]]
            if "b6_list" in _p:
                st.session_state["b6_list"] = list(_p["b6_list"])
            if "fv6_list" in _p:
                st.session_state["fv6_list"] = [tuple(x) for x in _p["fv6_list"]]
            if "bsp_list" in _p:
                st.session_state["bsp_list"] = [tuple(x) for x in _p["bsp_list"]]
            loaded += 1
        except:
            pass

    return loaded


# ============================
# Historical Vol Storage
# ============================

def save_vol_snapshot(user_id: str, currency: str, label: str, notes: str = ""):
    # Normalise admin email so snapshots are always under one canonical user_id
    _ADMIN_ALIASES = {"wpo70@icloud.com": "wpo@rateedge.au"}
    user_id = _ADMIN_ALIASES.get(user_id, user_id)
    """Save current vol matrix and SABR params as historical snapshot"""
    from datetime import datetime
    
    conn = get_db_connection()
    if not conn:
        return False
    
    try:
        # Get current vol data from session
        vol_data = st.session_state.get("vol_data", {}).get(currency, {})
        atm = vol_data.get("atm")
        sabr_alpha = vol_data.get("alpha")
        sabr_beta = vol_data.get("beta")
        sabr_rho = vol_data.get("rho")
        sabr_nu = vol_data.get("nu")

        if atm is None:
            st.error(f"No ATM vol data loaded for {currency}")
            return False

        # Convert DataFrame to JSON
        atm_json = atm.to_dict(orient="records")
        
        sabr_alpha_json = sabr_alpha.to_dict(orient="records") if sabr_alpha is not None else None
        sabr_beta_json = sabr_beta.to_dict(orient="records") if sabr_beta is not None else None
        sabr_rho_json = sabr_rho.to_dict(orient="records") if sabr_rho is not None else None
        sabr_nu_json = sabr_nu.to_dict(orient="records") if sabr_nu is not None else None
        
        # atm_prems saved as NULL — serialization too slow for large matrices
        atm_prems_json = None

        # Insert into vol_history table — always save as 'shared' so all users can load
        cur = conn.cursor()
        cur.execute("""
            INSERT INTO vol_history 
            (user_id, currency, snapshot_date, label, atm_vols, atm_prems, sabr_alpha, sabr_beta, sabr_rho, sabr_nu, notes)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id
        """, (
            'shared', 
            currency, 
            datetime.now(),
            label,
            Json({"values": atm_json}),
            Json({"values": atm_prems_json}) if atm_prems_json else None,
            Json({"values": sabr_alpha_json}) if sabr_alpha_json else None,
            Json({"values": sabr_beta_json}) if sabr_beta_json else None,
            Json({"values": sabr_rho_json}) if sabr_rho_json else None,
            Json({"values": sabr_nu_json}) if sabr_nu_json else None,
            notes
        ))
        
        snapshot_id = cur.fetchone()[0]
        conn.commit()
        cur.close()
        conn.close()
        
        return snapshot_id
        
    except Exception as e:
        st.error(f"Failed to save snapshot: {e}")
        return False


@st.cache_data(ttl=60, show_spinner=False)
def list_vol_snapshots(user_id: str, currency: str = None):
    """List all historical vol snapshots for a user"""
    # Normalise: both admin emails share the same snapshots
    _ADMIN_ALIASES = {"wpo70@icloud.com": "wpo@rateedge.au", "wpo@rateedge.au": "wpo@rateedge.au"}
    user_id = _ADMIN_ALIASES.get(user_id, user_id)
    conn = get_db_connection()
    if not conn:
        return []
    
    try:
        cur = conn.cursor()
        if currency:
            cur.execute("""
                SELECT id, currency, snapshot_date, label, notes, created_at
                FROM vol_history
                WHERE (user_id = %s OR user_id = %s OR user_id = 'shared') AND currency = %s
                ORDER BY snapshot_date DESC, created_at DESC
            """, ('wpo@rateedge.au', 'wpo70@icloud.com', currency))
        else:
            cur.execute("""
                SELECT id, currency, snapshot_date, label, notes, created_at
                FROM vol_history
                WHERE (user_id = %s OR user_id = %s OR user_id = 'shared')
                ORDER BY snapshot_date DESC, created_at DESC
            """, ('wpo@rateedge.au', 'wpo70@icloud.com',))
        
        snapshots = cur.fetchall()
        cur.close()
        conn.close()
        
        return [
            {
                "id": s[0],
                "currency": s[1],
                "snapshot_date": s[2],
                "label": s[3],
                "notes": s[4],
                "created_at": s[5]
            }
            for s in snapshots
        ]
        
    except Exception as e:
        st.error(f"Failed to list snapshots: {e}")
        return []


def load_vol_snapshot(snapshot_id: int):
    """Load a historical vol snapshot"""
    conn = get_db_connection()
    if not conn:
        return None
    
    try:
        cur = conn.cursor()
        cur.execute("""
            SELECT currency, atm_vols, sabr_alpha, sabr_beta, sabr_rho, sabr_nu, label, snapshot_date
            FROM vol_history
            WHERE id = %s
        """, (snapshot_id,))
        
        row = cur.fetchone()
        cur.close()
        conn.close()
        
        if not row:
            return None
        
        currency, atm_vols, sabr_alpha, sabr_beta, sabr_rho, sabr_nu, label, snapshot_date = row
        
        # Convert JSON to DataFrames
        atm_df = pd.DataFrame(atm_vols["values"]) if atm_vols else None
        sabr_alpha_df = pd.DataFrame(sabr_alpha["values"]) if sabr_alpha else None
        sabr_beta_df = pd.DataFrame(sabr_beta["values"]) if sabr_beta else None
        sabr_rho_df = pd.DataFrame(sabr_rho["values"]) if sabr_rho else None
        sabr_nu_df = pd.DataFrame(sabr_nu["values"]) if sabr_nu else None
        
        return {
            "currency": currency,
            "label": label,
            "snapshot_date": snapshot_date,
            "atm": atm_df,
            "alpha": sabr_alpha_df,
            "beta": sabr_beta_df,
            "rho": sabr_rho_df,
            "nu": sabr_nu_df
        }
        
    except Exception as e:
        st.error(f"Failed to load snapshot: {e}")
        return None


def delete_vol_snapshot(snapshot_id: int):
    """Delete a historical vol snapshot"""
    conn = get_db_connection()
    if not conn:
        return False
    
    try:
        cur = conn.cursor()
        cur.execute("DELETE FROM vol_history WHERE id = %s", (snapshot_id,))
        conn.commit()
        cur.close()
        conn.close()
        return True
        
    except Exception as e:
        st.error(f"Failed to delete snapshot: {e}")
        return False


def save_sod_report(user_id: str, report_date, usd_t1_label: str, usd_t2_label: str,
                    aud_snap_label: str, report_data: dict, notes: str = "") -> Optional[int]:
    """Save a SOD report to the database."""
    conn = get_db_connection()
    if not conn:
        return None
    try:
        cur = conn.cursor()
        cur.execute("""
            INSERT INTO sod_reports (user_id, report_date, usd_t1_label, usd_t2_label, aud_snap_label, report_data, notes)
            VALUES (%s, %s, %s, %s, %s, %s, %s)
            RETURNING id
        """, (user_id, report_date, usd_t1_label, usd_t2_label, aud_snap_label,
              Json(report_data), notes))
        report_id = cur.fetchone()[0]
        conn.commit()
        cur.close()
        conn.close()
        return report_id
    except Exception as e:
        st.error(f"Failed to save SOD report: {e}")
        return None


def list_sod_reports(user_id: str, limit: int = 30) -> list:
    """List saved SOD reports for a user."""
    conn = get_db_connection()
    if not conn:
        return []
    try:
        cur = conn.cursor()
        cur.execute("""
            SELECT id, report_date, created_at, usd_t1_label, usd_t2_label, aud_snap_label, notes
            FROM sod_reports
            WHERE user_id = %s
            ORDER BY report_date DESC, created_at DESC
            LIMIT %s
        """, (user_id, limit))
        rows = cur.fetchall()
        cur.close()
        conn.close()
        return [{"id": r[0], "report_date": r[1], "created_at": r[2],
                 "usd_t1": r[3], "usd_t2": r[4], "aud_snap": r[5], "notes": r[6]}
                for r in rows]
    except Exception as e:
        return []


def load_sod_report(report_id: int) -> Optional[dict]:
    """Load a SOD report from the database."""
    conn = get_db_connection()
    if not conn:
        return None
    try:
        cur = conn.cursor()
        cur.execute("""
            SELECT report_date, usd_t1_label, usd_t2_label, aud_snap_label, report_data, notes, created_at
            FROM sod_reports WHERE id = %s
        """, (report_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if not row:
            return None
        return {"report_date": row[0], "usd_t1": row[1], "usd_t2": row[2],
                "aud_snap": row[3], "data": row[4], "notes": row[5], "created_at": row[6]}
    except Exception as e:
        return None


def delete_sod_report(report_id: int) -> bool:
    """Delete a SOD report."""
    conn = get_db_connection()
    if not conn:
        return False
    try:
        cur = conn.cursor()
        cur.execute("DELETE FROM sod_reports WHERE id = %s", (report_id,))
        conn.commit()
        cur.close()
        conn.close()
        return True
    except Exception:
        return False


def publish_blotter_mids(ccy: str, mids: dict) -> int:
    """Publish mid market values to blotter_mids table for the React blotter to consume.
    mids = {key: {"value": float, "label": str}}
    Returns number of rows upserted. Uses executemany for performance.
    """
    conn = get_db_connection()
    if not conn:
        return 0
    try:
        cur = conn.cursor()
        rows = []
        for key, data in mids.items():
            val = data.get("value")
            lbl = data.get("label", "")
            if val is None:
                continue
            rows.append((ccy, key, float(val), lbl))
        if not rows:
            conn.close()
            return 0
        # True batch upsert via execute_values
        from psycopg2.extras import execute_values as _ev
        _ev(cur, """
            INSERT INTO blotter_mids (ccy, key, value, label, updated_at)
            VALUES %s
            ON CONFLICT (ccy, key) DO UPDATE
                SET value = EXCLUDED.value,
                    label = EXCLUDED.label,
                    updated_at = NOW()
        """, rows, template="(%s, %s, %s, %s, NOW())")
        conn.commit()
        cur.close()
        conn.close()
        return len(rows)
    except Exception as e:
        st.error(f"Failed to publish blotter mids: {e}")
        return 0


def export_vol_surface_to_excel(currency: str, include_sabr: bool = True) -> Optional[bytes]:
    """Export vol surface (ATM + optionally SABR) to Excel file"""
    from io import BytesIO
    
    try:
        # Get vol data
        vol_data = st.session_state.get("vol_data", {}).get(currency, {})
        atm = vol_data.get("atm")
        
        if atm is None or atm.empty:
            return None
        
        # Create Excel file in memory
        output = BytesIO()
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            # Write ATM vol surface — ensure Expiry is first column, round to 2dp
            atm_export = atm.copy()
            if "Expiry" in atm_export.columns and atm_export.columns[0] != "Expiry":
                cols = ["Expiry"] + [c for c in atm_export.columns if c != "Expiry"]
                atm_export = atm_export[cols]
            for _c in atm_export.columns:
                if _c != "Expiry":
                    atm_export[_c] = atm_export[_c].round(2)
            atm_export.to_excel(writer, sheet_name=f"ATM_Vols_{currency}", index=False)

            # Write ATM forward premium surface — use the pre-computed matrix from Curves tab
            try:
                _prem_store = st.session_state.get("atm_prem_matrix", {}).get(currency, {})
                _prem_df = _prem_store.get("prem")
                if _prem_df is not None and not _prem_df.empty:
                    _prem_export = _prem_df.copy()
                    # prem_df has Expiry as index — reset it to column
                    _prem_export = _prem_export.reset_index()
                    if "Expiry" in _prem_export.columns and _prem_export.columns[0] != "Expiry":
                        _pcols = ["Expiry"] + [c for c in _prem_export.columns if c != "Expiry"]
                        _prem_export = _prem_export[_pcols]
                    # Round to 2dp
                    for _c in _prem_export.columns:
                        if _c != "Expiry":
                            _prem_export[_c] = _prem_export[_c].round(2)
                    _prem_export.to_excel(writer, sheet_name=f"ATM_Prem_{currency}", index=False)
            except Exception:
                pass

            # Write ATM forward swap rates
            try:
                _fwd_df = st.session_state.get("fwd_matrix", {}).get(currency)
                if _fwd_df is not None and not _fwd_df.empty:
                    _fwd_export = _fwd_df.copy()
                    if _fwd_export.index.name:
                        _fwd_export = _fwd_export.reset_index()
                    if "Expiry" in _fwd_export.columns and _fwd_export.columns[0] != "Expiry":
                        _fcols = ["Expiry"] + [c for c in _fwd_export.columns if c != "Expiry"]
                        _fwd_export = _fwd_export[_fcols]
                    # Round fwd rates to 4dp
                    for _c in _fwd_export.columns:
                        if _c != "Expiry":
                            _fwd_export[_c] = _fwd_export[_c].round(4)
                    _fwd_export.to_excel(writer, sheet_name=f"ATM_Fwd_{currency}", index=False)
            except Exception:
                pass

            # Write SABR parameters if requested and available
            if include_sabr:
                sabr_alpha = vol_data.get("alpha")
                sabr_beta = vol_data.get("beta")
                sabr_rho = vol_data.get("rho")
                sabr_nu = vol_data.get("nu")
                
                if sabr_alpha is not None:
                    sabr_alpha.to_excel(writer, sheet_name=f"SABR_Alpha_{currency}", index=False)
                if sabr_beta is not None:
                    sabr_beta.to_excel(writer, sheet_name=f"SABR_Beta_{currency}", index=False)
                if sabr_rho is not None:
                    sabr_rho.to_excel(writer, sheet_name=f"SABR_Rho_{currency}", index=False)
                if sabr_nu is not None:
                    sabr_nu.to_excel(writer, sheet_name=f"SABR_Nu_{currency}", index=False)
            
            # Add metadata sheet
            metadata = pd.DataFrame({
                "Property": ["Currency", "Export Date", "Export Time"],
                "Value": [
                    currency,
                    pd.Timestamp.now().strftime('%Y-%m-%d'),
                    pd.Timestamp.now().strftime('%H:%M:%S'),
                ]
            })
            metadata.to_excel(writer, sheet_name="Metadata", index=False)
        
        output.seek(0)
        return output.getvalue()
        
    except Exception as e:
        st.error(f"Export failed: {e}")
        return None


# ============================
# Data structures
# ============================

@dataclass
class SwaptionTicket:
    side: str
    payoff_type: str  # "vanilla", "digital", "straddle"
    notional: float
    currency: str
    expiry_years: float
    swap_tenor_years: float
    forward: float
    strike: float
    vol: float
    discount_rate: float
    annuity: float
    model: str  # "Black" or "Normal"
    payout_bp: float = 1.0
    label: str = ""
    use_curve: bool = False

    def df(self, t: Optional[float] = None) -> float:
        if t is None:
            t = self.expiry_years
        return math.exp(-self.discount_rate * t)


# ============================
# Helper functions
# ============================

def label_to_years(lbl: str) -> float:
    from datetime import date as _date, datetime as _dt
    try:
        _f = float(lbl)
        if _f >= 0:
            return _f
    except (TypeError, ValueError):
        pass
    if lbl is None or str(lbl).strip() == "" or str(lbl).strip().lower() in ("none","nan","expiry"):
        return 0.0
    x = str(lbl).strip()
    # Handle DD/MM/YYYY or YYYY-MM-DD date strings
    for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
        try:
            target = _dt.strptime(x, fmt).date()
            days = (target - _date.today()).days
            return max(days / 365.0, 1/365.0)
        except ValueError:
            pass
    xl = x.lower()
    if xl.endswith("d"):
        return float(xl[:-1]) / 365.0
    if xl.endswith("w"):
        return float(xl[:-1]) / 52.0
    if xl.endswith("m"):
        return float(xl[:-1]) / 12.0
    if xl.endswith("y"):
        return float(xl[:-1])
    return float(xl)


def load_atm_surface(df: pd.DataFrame, name: str) -> pd.DataFrame:
    if "Expiry" not in df.columns:
        raise ValueError(f"{name} must have an 'Expiry' column")
    return df.copy()


def ensure_sabr_matrix(df: pd.DataFrame, name: str) -> pd.DataFrame:
    if "Expiry" not in df.columns:
        raise ValueError(f"{name} must have an 'Expiry' column")
    return df.copy()


def get_matrix_value(mat: Optional[pd.DataFrame],
                     expiry_label: str,
                     tenor_years: float) -> Optional[float]:
    if mat is None or mat.empty:
        return None

    # Normalise: work on a copy so we never mutate the stored surface
    if mat.index.name is not None and str(mat.index.name).lower() == "expiry":
        mat = mat.reset_index().rename(columns={mat.index.name: "Expiry"})
    elif "Expiry" not in mat.columns:
        _col_match = next((c for c in mat.columns if c.lower() == "expiry"), None)
        if _col_match:
            mat = mat.rename(columns={_col_match: "Expiry"})
        elif mat.index.dtype == object:
            # Index contains expiry labels — reset without name check
            mat = mat.reset_index().rename(columns={"index": "Expiry"})

    _tcols = [c for c in mat.columns if c != "Expiry"]
    if not _tcols:
        return None

    _ten_yrs = np.array([label_to_years(str(c)) for c in _tcols], dtype=float)
    _exp_yrs = mat["Expiry"].apply(lambda x: label_to_years(str(x).strip().lower())).values.astype(float)
    _exp_y_req = label_to_years(str(expiry_label).strip().lower())

    # Fast path: exact expiry row match
    _lbl = str(expiry_label).strip().lower()
    _row_match = mat[mat["Expiry"].astype(str).str.strip().str.lower() == _lbl]
    if not _row_match.empty:
        _row_vals = pd.to_numeric(_row_match.iloc[0][_tcols], errors='coerce').values.astype(float)
        _mask = ~np.isnan(_row_vals)
        if _mask.sum() == 0: return None
        return float(np.interp(tenor_years, _ten_yrs[_mask], _row_vals[_mask]))

    # Slow path: interpolate across expiry axis too
    _col_vals = []
    for _i in range(len(mat)):
        _row = pd.to_numeric(mat[_tcols].iloc[_i], errors='coerce').values.astype(float)
        _mask = ~np.isnan(_row)
        if _mask.sum() == 0: _col_vals.append(np.nan); continue
        _col_vals.append(float(np.interp(tenor_years, _ten_yrs[_mask], _row[_mask])))
    _col_vals = np.array(_col_vals, dtype=float)
    _valid = ~np.isnan(_col_vals)
    if _valid.sum() == 0: return None
    return float(np.interp(_exp_y_req, _exp_yrs[_valid], _col_vals[_valid]))


def get_sabr_params_from_matrices(a: Optional[pd.DataFrame],
                                  b: Optional[pd.DataFrame],
                                  r: Optional[pd.DataFrame],
                                  n: Optional[pd.DataFrame],
                                  expiry_label: str,
                                  tenor_years: float) -> Optional[dict]:
    alpha = get_matrix_value(a, expiry_label, tenor_years)
    beta = get_matrix_value(b, expiry_label, tenor_years)
    rho = get_matrix_value(r, expiry_label, tenor_years)
    nu = get_matrix_value(n, expiry_label, tenor_years)
    if any(x is None for x in (alpha, beta, rho, nu)):
        return None
    return dict(alpha=alpha, beta=beta, rho=rho, nu=nu)


def sabr_implied_vol_black(F: float, K: float, T: float,
                           alpha: float, beta: float,
                           rho: float, nu: float,
                           eps: float = 1e-7) -> float:
    """Hagan SABR approximation for Black vols."""
    F = float(F)
    K = float(K)
    alpha = float(alpha)
    beta = float(beta)
    rho = float(rho)
    nu = float(nu)

    if T <= 0 or alpha <= 0:
        return 0.0

    # ATM case
    if abs(F - K) < eps:
        Fmid = F
        term1 = alpha / (Fmid ** (1 - beta))
        term2 = (
            ((1 - beta) ** 2 / 24.0) * (alpha ** 2 / (Fmid ** (2 - 2 * beta))) +
            0.25 * rho * beta * nu * alpha / (Fmid ** (1 - beta)) +
            (2 - 3 * rho * rho) * nu * nu / 24.0
        ) * T
        return term1 * (1 + term2)

    # Away from ATM
    FK = F * K
    logFK = math.log(F / K)
    
    # Leading order term
    FK_beta = FK ** ((1 - beta) / 2.0)
    
    # z and chi(z) for the smile
    z = (nu / alpha) * FK_beta * logFK
    
    if abs(z) < eps:
        x_z = 1.0
    else:
        sqrt_term = math.sqrt(1 - 2 * rho * z + z * z)
        x_z = z / math.log((sqrt_term + z - rho) / (1 - rho))
    
    # Numerator correction for logFK
    num_corr = 1 + ((1 - beta) ** 2 / 24.0) * (logFK ** 2) + ((1 - beta) ** 4 / 1920.0) * (logFK ** 4)
    
    # Denominator (time-dependent correction)
    den_corr = 1 + (
        ((1 - beta) ** 2 / 24.0) * (alpha ** 2 / (FK ** (1 - beta))) +
        0.25 * rho * beta * nu * alpha / FK_beta +
        (2 - 3 * rho * rho) * nu * nu / 24.0
    ) * T
    
    vol = (alpha / FK_beta) * x_z * num_corr / den_corr
    return max(vol, 0.0)


def sabr_normal_atm_vol(F: float, T: float, alpha: float, beta: float, rho: float, nu: float) -> float:
    """Normal (Bachelier) SABR ATM vol approximation."""
    if T <= 0 or alpha <= 0 or F <= 0:
        return 0.0
    return alpha * (F ** beta) * (1.0 + (2.0 - 3.0 * rho ** 2) / 24.0 * nu ** 2 * T)


def sabr_normal_vol_smile(F: float, K: float, T: float,
                           alpha: float, beta: float, rho: float, nu: float) -> float:
    """Full Normal SABR smile vol (Antonov et al.). Returns vol in same units as alpha.
    For ATM (K≈F) reduces to sabr_normal_atm_vol.
    Formula: σ_N = alpha × (FK)^(β/2) × z/χ(z) × B
    """
    if T <= 0 or alpha <= 0 or F <= 0 or K <= 0:
        return sabr_normal_atm_vol(F, T, alpha, beta, rho, nu)
    if abs(K - F) < 1e-8:
        return sabr_normal_atm_vol(F, T, alpha, beta, rho, nu)
    try:
        FK = F * K
        FK_mid = FK ** (beta / 2.0)          # (FK)^(β/2)  — Normal SABR uses multiply
        FK_mid_inv = FK ** ((1 - beta) / 2.0) # (FK)^((1-β)/2) — for B correction terms
        log_FK = math.log(F / K)
        z = (nu / alpha) * FK_mid_inv * log_FK
        if abs(z) < 1e-7:
            x_z = 1.0
        else:
            _sq = math.sqrt(1 - 2 * rho * z + z ** 2)
            _denom = math.log((_sq + z - rho) / (1 - rho))
            x_z = z / _denom if abs(_denom) > 1e-10 else 1.0
        A = alpha * FK_mid  # Normal SABR: α × (FK)^(β/2)
        B = 1 + ((1 - beta) ** 2 / 24 * alpha ** 2 / FK ** (1 - beta) +
                  rho * beta * nu * alpha / (4 * FK ** ((1 - beta) / 2)) +
                  (2 - 3 * rho ** 2) / 24 * nu ** 2) * T
        return A * x_z * B
    except Exception:
        return sabr_normal_atm_vol(F, T, alpha, beta, rho, nu)


def sabr_implied_alpha_from_atm(atm_vol_normal: float, F: float, T: float,
                                  beta: float, rho: float, nu: float) -> float:
    """Back out alpha from ATM normal vol, given fixed beta/rho/nu.
    Solves: atm_vol = alpha * F^beta * (1 + (2-3ρ,ν~)/24 * ×~ * T)
    """
    if T <= 0 or F <= 0:
        return 0.0
    denom = (F ** beta) * (1.0 + (2.0 - 3.0 * rho ** 2) / 24.0 * nu ** 2 * T)
    if abs(denom) < 1e-12:
        return 0.0
    return atm_vol_normal / denom


# ============================
# Curve construction
# ============================

def load_curve(df: pd.DataFrame, name: str) -> pd.DataFrame:
    if {"Maturity (Years)", "Zero Rate (%)"}.issubset(df.columns):
        out = df[["Maturity (Years)", "Zero Rate (%)"]].copy()
        out.rename(columns={"Maturity (Years)": "MaturityY", "Zero Rate (%)": "ZeroRatePct"}, inplace=True)
        out = out.sort_values("MaturityY").reset_index(drop=True)
        return out
    raise ValueError(f"{name}: expected columns 'Maturity (Years)', 'Zero Rate (%)'")


def interpolate_zero(curve: pd.DataFrame, t: float) -> float:
    xs = curve["MaturityY"].to_numpy().astype(float)
    ys = curve["ZeroRatePct"].to_numpy().astype(float) / 100.0
    if t <= xs[0]:
        return float(ys[0])
    if t >= xs[-1]:
        return float(ys[-1])
    dfs = np.exp(-ys * xs)
    df_t = np.exp(np.interp(t, xs, np.log(dfs)))
    return -math.log(df_t) / t


def df_from_curve(curve: pd.DataFrame, t: float) -> float:
    z = interpolate_zero(curve, t)
    return math.exp(-z * t)


def _next_bd(d: "date") -> "date":
    """Next business day (Mon-Fri, no holiday calendar)."""
    from datetime import date as _date, timedelta as _td
    while d.weekday() >= 5:
        d += _td(days=1)
    return d

def _add_months(d: "date", months: int) -> "date":
    """Add whole months, clamping to end-of-month."""
    import calendar as _cal
    from datetime import date as _date
    m = d.month - 1 + months
    y = d.year + m // 12
    m = m % 12 + 1
    return _date(y, m, min(d.day, _cal.monthrange(y, m)[1]))

def _add_years(d: "date", years: int) -> "date":
    from datetime import date as _date
    try:
        return d.replace(year=d.year + years)
    except ValueError:
        return _date(d.year + years, d.month, 28)

def _mod_fol(d: "date") -> "date":
    """Modified following: if adjusted date falls in next month, go backward."""
    from datetime import timedelta as _td
    nd = _next_bd(d)
    if nd.month != d.month:
        pd_ = d
        while pd_.weekday() >= 5:
            pd_ -= _td(days=1)
        return pd_
    return nd

def _act365(d1: "date", d2: "date") -> float:
    return (d2 - d1).days / 365.0

def _pricing_date() -> "date":
    """Today's date for schedule generation."""
    from datetime import date as _date
    import streamlit as _st
    try:
        d = _st.session_state.get("pricing_date")
        if d: return d
    except Exception:
        pass
    return _date.today()

def _spot_date(spot_lag_bd: int) -> "date":
    """Spot date = today + spot_lag business days."""
    from datetime import timedelta as _td
    d = _pricing_date()
    count = 0
    while count < spot_lag_bd:
        d += _td(days=1)
        if d.weekday() < 5:
            count += 1
    return d

def _fwd_start_date(expiry_years: float, spot_lag_bd: int) -> "date":
    """Forward start date: spot + expiry (mod-fol). Uses days for <1m, months otherwise."""
    from datetime import timedelta as _td
    spot = _spot_date(spot_lag_bd)
    total_days = expiry_years * 365.25
    total_months = int(round(expiry_years * 12))
    if total_days < 27:
        # Sub-monthly: add whole days then mod-fol
        raw = spot + _td(days=int(round(total_days)))
    else:
        raw = _add_months(spot, total_months)
    return _mod_fol(raw)

def _build_date_schedule(fwd_start: "date", tenor_years: float, months_per_period: int) -> List[Tuple[float, float]]:
    """
    Build actual payment schedule using mod-fol date arithmetic.
    Returns list of (time_in_years_from_today, act365_accrual).
    Final cashflow uses total months (not rounded years) to handle 18m, 1.5Y etc correctly.
    """
    today = _pricing_date()
    total_months = int(round(tenor_years * 12))
    n = int(round(tenor_years * (12 / months_per_period)))
    schedule = []
    prev = fwd_start
    for i in range(1, n + 1):
        # Always use months arithmetic - last cashflow uses total_months exactly
        raw = _add_months(fwd_start, i * months_per_period if i < n else total_months)
        pay = _mod_fol(raw)
        accrual = _act365(prev, pay)
        t_years = _act365(today, pay)
        schedule.append((t_years, accrual))
        prev = pay
    return schedule

def build_aud_schedule(expiry: float, tenor: float) -> List[Tuple[float, float]]:
    """AUD: T+1BD spot, mod-fol, Act/365. Q/Q (3m) for ≤3Y, S/S (6m) for >3Y."""
    months_per = 3 if tenor <= 3.0 else 6
    fwd_start = _fwd_start_date(expiry, spot_lag_bd=1)
    return _build_date_schedule(fwd_start, tenor, months_per)


def _act360(d1: "date", d2: "date") -> float:
    """Act/360 day count — USD SOFR convention."""
    return (d2 - d1).days / 360.0


def build_usd_sofr_schedule(expiry: float, tenor: float) -> List[Tuple[float, float]]:
    """
    USD SOFR swaption: T+2 NY BD spot, mod-fol, Act/360, annual payments both legs.
    Returns list of (time_in_years_from_today, act360_accrual).
    """
    today = _pricing_date()
    fwd_start = _fwd_start_date(expiry, spot_lag_bd=2)
    months_per_period = 12  # annual
    total_months = int(round(tenor * 12))
    n = int(round(tenor * (12 / months_per_period)))
    schedule = []
    prev = fwd_start
    for i in range(1, n + 1):
        raw = _add_months(fwd_start, i * months_per_period if i < n else total_months)
        pay = _mod_fol(raw)
        accrual = _act360(prev, pay)   # Act/360 for USD SOFR
        t_years = _act365(today, pay)  # time to payment in years (365 basis for discounting)
        schedule.append((t_years, accrual))
        prev = pay
    return schedule


def build_generic_schedule(expiry: float, tenor: float, freq: float = 0.5, spot_lag: float = 1.0) -> List[Tuple[float, float]]:
    """T+2BD spot (NZD/USD), mod-fol, Act/365. freq: 0.25=Q/Q, 0.5=S/S."""
    months_per = int(round(freq * 12))
    fwd_start = _fwd_start_date(expiry, spot_lag_bd=int(round(spot_lag)))
    return _build_date_schedule(fwd_start, tenor, months_per)


def forward_and_annuity_from_curve(curve: pd.DataFrame,
                                   ccy: str,
                                   expiry: float,
                                   tenor: float,
                                   ois_curve: Optional[pd.DataFrame] = None,
                                   freq_override: Optional[float] = None) -> Tuple[float, float, List[Tuple[float, float]]]:
    """
    Calculate forward swap rate and annuity.
    Uses LINEAR zero-rate interpolation (same as fast_forward_rate / matrix) so
    the swaption pricer forward exactly matches the Rate/Vol Matrix.
    freq_override: 0.25 = Q/Q, 0.5 = S/S, None = market convention
    """
    # Fast session-level cache keyed by curve commit ID (no hashing)
    try:
        _cid = st.session_state.get("_curve_commit_ids", {}).get(ccy, 0)
        _oid = st.session_state.get("_curve_commit_ids", {}).get(f"{ccy}_ois", 0) if ois_curve is not None else -1
        _ck = (ccy, _cid, _oid, round(expiry, 6), round(tenor, 6), round(freq_override or -1, 6))
        _fc = st.session_state.setdefault("_fwd_ann_cache", {})
        if _ck in _fc:
            return _fc[_ck]
    except Exception:
        _ck = None; _fc = {}

    if freq_override is not None:
        # T+2 BD for NZD/USD, T+1 BD for AUD (AFMA calendar   —   year frac approx here)
        spot_lag = 2.0 / 252.0 if ccy in ["NZD", "USD"] else 1.0 / 252.0
        sched = build_generic_schedule(expiry, tenor, freq=freq_override, spot_lag=spot_lag * 252)
    elif ccy == "AUD":
        sched = build_aud_schedule(expiry, tenor)
    elif ccy == "NZD":
        freq_nzd = 0.25 if tenor <= 2.0 else 0.5
        sched = build_generic_schedule(expiry, tenor, freq=freq_nzd, spot_lag=2.0)
    elif ccy == "USD":
        sched = build_usd_sofr_schedule(expiry, tenor)
    else:
        sched = build_generic_schedule(expiry, tenor, freq=0.5, spot_lag=1.0)

    if not sched:
        return 0.0, 0.0, []

    # IRS for projection, OIS for annuity discounting (dual-curve)
    basis_6v3 = get_basis_curve(ccy, "6v3") if ccy == "AUD" else None

    # AUD: select projection curve by tenor for consistency with forward matrix
    # tenor <=3Y (Q/Q): use QQ-full extended curve (smooth, basis-adjusted to 30Y)
    # tenor  >3Y (S/S): use SS curve (seeded at QQ junction, SS par rates 4Y+)
    if ccy == "AUD":
        _zc_qq_full = st.session_state.get("_aud_zc_qq_full")
        _aud_ss = st.session_state.get("_aud_zc_ss")
        if tenor <= 3.0 and _zc_qq_full and len(_zc_qq_full) >= 10:
            _xs = np.array(sorted(_zc_qq_full.keys()))
            _ys = np.array([_zc_qq_full[k] for k in _xs])
            _proj_curve = pd.DataFrame({"MaturityY": _xs, "ZeroRatePct": _ys})
        elif tenor > 3.0 and _aud_ss and len(_aud_ss) >= 10:
            _xs = np.array(sorted(_aud_ss.keys()))
            _ys = np.array([_aud_ss[k] for k in _xs])
            _proj_curve = pd.DataFrame({"MaturityY": _xs, "ZeroRatePct": _ys})
        elif st.session_state.get("_aud_proj_curve") is not None:
            _proj_curve = st.session_state["_aud_proj_curve"]
        else:
            _proj_curve = curve
    else:
        _proj_curve = curve

    def _df_proj(crv: pd.DataFrame, t: float, freq: float) -> float:
        """Projection discount factor with convention-aware basis adjustment for AUD."""
        xs = crv["MaturityY"].to_numpy().astype(float)
        ys = crv["ZeroRatePct"].to_numpy().astype(float) / 100.0
        z = float(np.interp(t, xs, ys))
        # Basis already incorporated in QQ-full and SS projection curves - no double adjustment
        return math.exp(-z * t)

    def _df_disc(crv: pd.DataFrame, t: float) -> float:
        xs = crv["MaturityY"].to_numpy().astype(float)
        ys = crv["ZeroRatePct"].to_numpy().astype(float) / 100.0
        z = float(np.interp(t, xs, ys))
        return math.exp(-z * t)

    disc_curve = ois_curve if ois_curve is not None else _proj_curve

    # Determine effective frequency from schedule (periods per year → years per period)
    _n_periods = len(sched)
    _total_time = sched[-1][0] - (sched[0][0] - sched[0][1]) if sched else 0.5
    _sched_freq = round(_total_time / _n_periods * 4) / 4 if _n_periods > 0 else 0.5  # round to nearest 0.25

    ann = 0.0
    for T_i, accrual in sched:
        ann += _df_disc(disc_curve, T_i) * accrual

    swap_start = sched[0][0] - sched[0][1]
    df_start = _df_proj(_proj_curve, swap_start, _sched_freq)
    df_end   = _df_proj(_proj_curve, sched[-1][0], _sched_freq)
    fwd = (df_start - df_end) / ann if ann > 0 else 0.0
    _result = (fwd, ann, sched)
    try:
        if _ck is not None and len(_fc) < 5000:
            _fc[_ck] = _result
    except Exception:
        pass
    return _result


# ============================
# Swaption pricing
# ============================

def black_swaption_vanilla(ticket: SwaptionTicket) -> dict:
    F = ticket.forward
    K = ticket.strike
    sigma = max(ticket.vol, 1e-8)
    T = max(ticket.expiry_years, 1e-8)
    df = ticket.df()
    annuity = ticket.annuity if ticket.annuity > 0 else ticket.swap_tenor_years

    if F <= 0 or K <= 0 or annuity <= 0:
        bpv = df * annuity * ticket.notional * 0.0001
        return {"pv": 0.0, "pv_bp": 0.0, "delta": 0.0, "gamma": 0.0, "vega": 0.0, "theta": 0.0, "bpv": bpv}

    lnFK = math.log(F / K)
    vol_sqrt_t = sigma * math.sqrt(T)
    d1 = (lnFK + 0.5 * sigma * sigma * T) / vol_sqrt_t
    d2 = d1 - vol_sqrt_t
    N = NormalDist().cdf
    phi = lambda x: math.exp(-0.5 * x * x) / math.sqrt(2 * math.pi)

    if ticket.side.lower().startswith("payer"):
        price_rate = F * N(d1) - K * N(d2)
        delta_ratio = N(d1)          # hedge ratio: 0.5 ATM = 50mm hedge per 100mm notional
    else:
        price_rate = K * N(-d2) - F * N(-d1)
        delta_ratio = -N(-d1)

    pv = df * annuity * ticket.notional * price_rate
    bpv = df * annuity * ticket.notional * 0.0001
    delta = delta_ratio * ticket.notional
    delta_dv01 = delta_ratio * bpv
    pv_bp_spot = pv / (ticket.notional * 0.0001) if ticket.notional > 0 else 0.0
    pv_bp_fwd  = annuity * price_rate * 10000 / df if (df > 0 and ticket.notional > 0) else pv_bp_spot
    pv_bp = pv_bp_fwd
    vega  = df * annuity * ticket.notional * F * phi(d1) * math.sqrt(T) * 0.0001
    gamma = df * annuity * ticket.notional * phi(d1) / (F * sigma * math.sqrt(T)) * 0.0001
    theta = -0.5 * df * annuity * ticket.notional * F * sigma * phi(d1) / 365.0

    return {"pv": pv, "pv_bp": pv_bp, "pv_bp_spot": pv_bp_spot, "pv_bp_fwd": pv_bp_fwd,
            "delta": delta, "delta_dv01": delta_dv01, "delta_ratio": delta_ratio,
            "gamma": gamma, "vega": vega, "theta": theta, "bpv": bpv}


def bachelier_swaption_vanilla(ticket: SwaptionTicket) -> dict:
    F = ticket.forward
    K = ticket.strike
    sigma_n = max(ticket.vol, 1e-8)
    T = max(ticket.expiry_years, 1e-8)
    df = ticket.df()
    annuity = ticket.annuity if ticket.annuity > 0 else ticket.swap_tenor_years

    if annuity <= 0:
        bpv = df * annuity * ticket.notional * 0.0001
        return {"pv": 0.0, "pv_bp": 0.0, "delta": 0.0, "gamma": 0.0, "vega": 0.0, "theta": 0.0, "bpv": bpv}

    d = (F - K) / (sigma_n * math.sqrt(T))
    phi = math.exp(-0.5 * d * d) / math.sqrt(2 * math.pi)
    N = NormalDist().cdf(d)

    if ticket.side.lower().startswith("payer"):
        price_rate = (F - K) * N + sigma_n * math.sqrt(T) * phi
        delta_ratio = N
    else:
        price_rate = (K - F) * (1 - N) + sigma_n * math.sqrt(T) * phi
        delta_ratio = -(1 - N)

    pv = df * annuity * ticket.notional * price_rate
    bpv = df * annuity * ticket.notional * 0.0001
    delta = delta_ratio * ticket.notional
    delta_dv01 = delta_ratio * bpv
    pv_bp_spot = pv / (ticket.notional * 0.0001) if ticket.notional > 0 else 0.0
    pv_bp_fwd  = annuity * price_rate * 10000 / df if (df > 0 and ticket.notional > 0) else pv_bp_spot
    pv_bp = pv_bp_fwd
    vega  = df * annuity * ticket.notional * math.sqrt(T) * phi * 0.0001
    gamma = df * annuity * ticket.notional * phi / (sigma_n * math.sqrt(T)) * 0.0001
    theta = -0.5 * df * annuity * ticket.notional * sigma_n * phi / math.sqrt(T) / 365.0

    return {"pv": pv, "pv_bp": pv_bp, "pv_bp_spot": pv_bp_spot, "pv_bp_fwd": pv_bp_fwd,
            "delta": delta, "delta_dv01": delta_dv01, "delta_ratio": delta_ratio,
            "gamma": gamma, "vega": vega, "theta": theta, "bpv": bpv}


def black_swaption_digital(ticket: SwaptionTicket) -> dict:
    F = ticket.forward
    K = ticket.strike
    sigma = max(ticket.vol, 1e-8)
    T = max(ticket.expiry_years, 1e-8)
    df = ticket.df()
    payout_rate = ticket.payout_bp * 0.0001
    annuity = ticket.annuity if ticket.annuity > 0 else ticket.swap_tenor_years

    lnFK = math.log(F / K)
    vol_sqrt_t = sigma * math.sqrt(T)
    d2 = (lnFK - 0.5 * sigma * sigma * T) / vol_sqrt_t
    N = NormalDist().cdf
    phi = lambda x: math.exp(-0.5 * x * x) / math.sqrt(2 * math.pi)

    if ticket.side.lower().startswith("payer"):
        prob = N(d2)
        delta_prob = phi(d2) / (F * sigma * math.sqrt(T))
    else:
        prob = N(-d2)
        delta_prob = -phi(d2) / (F * sigma * math.sqrt(T))

    pv = df * annuity * ticket.notional * payout_rate * prob
    delta = df * annuity * ticket.notional * payout_rate * delta_prob
    bpv = df * annuity * ticket.notional * 0.0001
    pv_bp = pv / bpv if bpv != 0 else 0.0

    return {"pv": pv, "pv_bp": pv_bp, "delta": delta, "gamma": 0.0, "vega": 0.0, "theta": 0.0, "bpv": bpv}


def bachelier_swaption_digital(ticket: SwaptionTicket) -> dict:
    F = ticket.forward
    K = ticket.strike
    sigma_n = max(ticket.vol, 1e-8)
    T = max(ticket.expiry_years, 1e-8)
    df = ticket.df()
    payout_rate = ticket.payout_bp * 0.0001
    annuity = ticket.annuity if ticket.annuity > 0 else ticket.swap_tenor_years

    d = (F - K) / (sigma_n * math.sqrt(T))
    phi = math.exp(-0.5 * d * d) / math.sqrt(2 * math.pi)
    N = NormalDist().cdf(d)

    if ticket.side.lower().startswith("payer"):
        prob = N
        delta_prob = phi / (sigma_n * math.sqrt(T))
    else:
        prob = 1 - N
        delta_prob = -phi / (sigma_n * math.sqrt(T))

    pv = df * annuity * ticket.notional * payout_rate * prob
    delta = df * annuity * ticket.notional * payout_rate * delta_prob
    bpv = df * annuity * ticket.notional * 0.0001
    pv_bp = pv / bpv if bpv != 0 else 0.0

    return {"pv": pv, "pv_bp": pv_bp, "delta": delta, "gamma": 0.0, "vega": 0.0, "theta": 0.0, "bpv": bpv}


def price_swaption(ticket: SwaptionTicket) -> dict:
    if ticket.model == "Black":
        if ticket.payoff_type == "vanilla":
            return black_swaption_vanilla(ticket)
        elif ticket.payoff_type == "digital":
            return black_swaption_digital(ticket)
        elif ticket.payoff_type == "straddle":
            t_p = SwaptionTicket(**{**ticket.__dict__, "side": "Payer", "payoff_type": "vanilla"})
            t_r = SwaptionTicket(**{**ticket.__dict__, "side": "Receiver", "payoff_type": "vanilla"})
            p1 = black_swaption_vanilla(t_p)
            p2 = black_swaption_vanilla(t_r)
            return {k: p1.get(k, 0.0) + p2.get(k, 0.0) for k in p1.keys()}
    else:
        if ticket.payoff_type == "vanilla":
            return bachelier_swaption_vanilla(ticket)
        elif ticket.payoff_type == "digital":
            return bachelier_swaption_digital(ticket)
        elif ticket.payoff_type == "straddle":
            t_p = SwaptionTicket(**{**ticket.__dict__, "side": "Payer", "payoff_type": "vanilla"})
            t_r = SwaptionTicket(**{**ticket.__dict__, "side": "Receiver", "payoff_type": "vanilla"})
            p1 = bachelier_swaption_vanilla(t_p)
            p2 = bachelier_swaption_vanilla(t_r)
            return {k: p1.get(k, 0.0) + p2.get(k, 0.0) for k in p1.keys()}
    return bachelier_swaption_vanilla(ticket)


# ============================
# Caps / Floors
# ============================

def black_caplet(notional: float, accrual: float,
                 F: float, K: float, sigma: float, T: float,
                 r: float, is_cap: bool = True) -> dict:
    if T <= 0 or sigma <= 0:
        return {"pv": 0.0, "delta": 0.0, "vega": 0.0, "gamma": 0.0}
    df = math.exp(-r * T)
    if F <= 0 or K <= 0:
        return {"pv": 0.0, "delta": 0.0, "vega": 0.0, "gamma": 0.0}
    lnFK = math.log(F / K)
    vol_sqrt_t = sigma * math.sqrt(T)
    d1 = (lnFK + 0.5 * sigma * sigma * T) / vol_sqrt_t
    d2 = d1 - vol_sqrt_t
    N = NormalDist().cdf
    phi = lambda x: math.exp(-0.5 * x * x) / math.sqrt(2 * math.pi)
    if is_cap:
        price_rate = F * N(d1) - K * N(d2)
        delta_rate = N(d1)
    else:
        price_rate = K * N(-d2) - F * N(-d1)
        delta_rate = -N(-d1)
    vega_rate = F * phi(d1) * math.sqrt(T)
    gamma_rate = phi(d1) / (F * sigma * math.sqrt(T))
    pv = notional * accrual * df * price_rate
    delta = notional * accrual * df * delta_rate * 0.0001   # DV01 contribution per caplet
    vega  = notional * accrual * df * vega_rate  * 0.0001
    gamma = notional * accrual * df * gamma_rate * 0.0001
    return {"pv": pv, "delta": delta, "vega": vega, "gamma": gamma}


def bachelier_caplet(notional: float, accrual: float,
                     F: float, K: float, sigma_n: float, T: float,
                     r: float, is_cap: bool = True) -> dict:
    if T <= 0 or sigma_n <= 0:
        return {"pv": 0.0, "delta": 0.0, "vega": 0.0, "gamma": 0.0}
    df = math.exp(-r * T)
    d = (F - K) / (sigma_n * math.sqrt(T))
    phi = math.exp(-0.5 * d * d) / math.sqrt(2 * math.pi)
    N = NormalDist().cdf(d)
    if is_cap:
        price_rate = (F - K) * N + sigma_n * math.sqrt(T) * phi
        delta_rate = N
    else:
        price_rate = (K - F) * (1 - N) + sigma_n * math.sqrt(T) * phi
        delta_rate = N - 1
    pv = notional * accrual * df * price_rate
    delta = notional * accrual * df * delta_rate * 0.0001      # DV01 contribution per caplet
    vega  = notional * accrual * df * math.sqrt(T) * phi       * 0.0001
    gamma = notional * accrual * df * phi / (sigma_n * math.sqrt(T)) * 0.0001
    return {"pv": pv, "delta": delta, "vega": vega, "gamma": gamma}


# ============================
# XVA helpers
# ============================

def simple_exposure_profile(pv0: float,
                            vega: float,
                            vol: float,
                            horizon_years: float,
                            n_steps: int = 20) -> Tuple[np.ndarray, np.ndarray]:
    ts = np.linspace(0.0, horizon_years, n_steps)
    ee = pv0 + vega * vol * np.sqrt(np.maximum(ts, 1e-8))
    return ts, np.maximum(ee, 0.0)


def cva_from_hazard(ee_times: np.ndarray,
                    ee_values: np.ndarray,
                    hazard_rate: float,
                    lgd: float,
                    discount_rate: float) -> float:
    h = max(hazard_rate, 0.0)
    ts = ee_times
    cvs = 0.0
    prev_pd = 0.0
    for t, ee in zip(ts, ee_values):
        pd_t = 1.0 - math.exp(-h * t)
        dPD = max(pd_t - prev_pd, 0.0)
        df = math.exp(-discount_rate * t)
        cvs += ee * dPD * df
        prev_pd = pd_t
    return -lgd * cvs


# ============================
# Caplet Vol Term Structure Builder
# Advanced Bootstrap Solver with Monotone Cubic Interpolation
# ============================

def price_caplets_with_vol_curve(ccy, tenor_y, caplet_vol_dict, notional_mm=1.0, expiry_y=0.0):
    """
    Price caplets using vol curve. Used by both bootstrap solver and pricer.
    expiry_y: forward start (0 = spot cap). Cap runs from expiry_y to expiry_y+tenor_y.
    The first fixing at expiry_y is known (forward rate) and skipped.
    Returns premium in bp per leg (not straddle).
    """
    _cc = st.session_state.get("config_curves", {}).get(ccy)
    curve = _cc if _cc is not None else get_ccy_curve(ccy)
    _ois_cb = st.session_state.get("config_basis", {}).get(ccy, {}).get("ois")
    ois_curve = _ois_cb if _ois_cb is not None else get_basis_curve(ccy, "ois")
    if ois_curve is None:
        ois_curve = curve
    
    # Build quarterly schedule from expiry_y to expiry_y + tenor_y
    cap_start = expiry_y if expiry_y > 0 else 1.0 / 252.0
    cap_end   = cap_start + tenor_y
    
    sched = []
    t = cap_start
    while t < cap_end - 1e-8:
        t_next = min(t + 0.25, cap_end)
        accrual = t_next - t
        sched.append((t_next, accrual))
        t = t_next
    
    total_pv = 0.0
    
    for i, (T_fix, accrual) in enumerate(sched):
        if i == 0:
            continue  # Skip first fixing
        
        # Get vol from curve - use exact T_fix, don't round
        if T_fix in caplet_vol_dict:
            vol_bp = caplet_vol_dict[T_fix]
        else:
            # Linear interpolation (same logic as get_caplet_vol_for_fixing)
            mats = sorted(caplet_vol_dict.keys())
            if T_fix < mats[0]:
                vol_bp = caplet_vol_dict[mats[0]]
            elif T_fix > mats[-1]:
                vol_bp = caplet_vol_dict[mats[-1]]
            else:
                for j in range(len(mats)-1):
                    if mats[j] <= T_fix <= mats[j+1]:
                        alpha = (T_fix - mats[j]) / (mats[j+1] - mats[j])
                        vol_bp = caplet_vol_dict[mats[j]] + alpha * (caplet_vol_dict[mats[j+1]] - caplet_vol_dict[mats[j]])
                        break
        
        sigma = vol_bp / 10000.0
        
        # Individual caplet forward
        period_start = max(T_fix - 0.25, 0.001)
        period_tenor = 0.25
        F_caplet, _, _ = forward_and_annuity_from_curve(curve, ccy, period_start, period_tenor, ois_curve)
        
        disc_rate = interpolate_zero(ois_curve, T_fix)
        
        # Price with F=K (ATM)
        res = bachelier_caplet(notional_mm * 1e6, accrual, F_caplet, F_caplet, sigma, T_fix, disc_rate, is_cap=True)
        total_pv += res["pv"]
    
    # Return premium in bp
    premium_bp = (total_pv / (notional_mm * 1e6)) * 10000.0
    return premium_bp


def build_caplet_vol_curve_from_surface(ccy: str, atm_surface):
    """
    Build caplet vol curve using SWAPTION SURFACE ONLY - no user spreads.
    CFS targets are derived from cumulative swaption premiums:
      - 1Y CFS target = 3m1y swaption premium (spot cap to 1Y)
      - 2Y CFS target = 1Y CFS + 1y1y swaption premium (wedge)
      - etc.
    This is the pure surface-implied caplet vol term structure.
    """
    import scipy.optimize as opt
    if atm_surface is None or atm_surface.empty:
        return None

    _cc = st.session_state.get("config_curves", {}).get(ccy)
    curve = _cc if _cc is not None else get_ccy_curve(ccy)
    _ois_cb = st.session_state.get("config_basis", {}).get(ccy, {}).get("ois")
    ois_curve = _ois_cb if _ois_cb is not None else get_basis_curve(ccy, "ois")
    if curve is None:
        return None
    if ois_curve is None:
        ois_curve = curve

    def get_swpt_prem(expiry_label, tenor_y):
        try:
            vol_bp = get_matrix_value(atm_surface, expiry_label, tenor_y)
            if vol_bp is None: return None
            exp_y = label_to_years(expiry_label)
            _, ann, _ = forward_and_annuity_from_curve(curve, ccy, exp_y, tenor_y, None)
            sigma_n = vol_bp / 10000.0
            sqrt_t = math.sqrt(max(exp_y, 0.001))
            return 2 * 0.3989 * sigma_n * sqrt_t * ann * 10000
        except:
            return None

    # Build cumulative CFS targets from swaption surface alone
    # Each CFS = sum of all swaption wedge premiums up to that maturity
    wedge_chain = [
        ("3m1y", "3m", 1.0, 1.0),    # 3m1y swaption → 1Y CFS
        ("1y1y", "1y", 1.0, 2.0),    # + 1y1y wedge  → 2Y CFS
        ("2y1y", "2y", 1.0, 3.0),    # + 2y1y wedge  → 3Y CFS
        ("3y1y", "3y", 1.0, 4.0),
        ("4y1y", "4y", 1.0, 5.0),
        ("5y2y", "5y", 2.0, 7.0),
        ("7y3y", "7y", 3.0, 10.0),
        ("10y2y","10y",2.0, 12.0),
        ("12y3y","12y",3.0, 15.0),
    ]

    cumulative_leg_prems = {}
    cumulative_prem = 0.0
    for lbl, exp, tenor, result_mat in wedge_chain:
        p = get_swpt_prem(exp, tenor)
        if p is None:
            break
        cumulative_prem += p / 2.0   # leg premium (straddle/2)
        cumulative_leg_prems[result_mat] = cumulative_prem

    if not cumulative_leg_prems:
        return None

    # Now bootstrap exactly as WEDGES mode, using these surface-derived targets
    caplet_vols = {}

    def price_caplets_flat_vol_inner(vol_bp, final_maturity_y):
        flat_curve = {round(t, 2): vol_bp for t in np.arange(0.25, final_maturity_y + 0.26, 0.25)}
        return price_caplets_with_vol_curve(ccy, final_maturity_y, flat_curve, notional_mm=1.0)

    # Step 1: solve 1Y flat vol
    if 1.0 in cumulative_leg_prems:
        try:
            vol_1y = opt.brentq(
                lambda v: price_caplets_flat_vol_inner(v, 1.0) - cumulative_leg_prems[1.0],
                1.0, 200.0, xtol=0.001
            )
            for t in [0.25, 0.5, 0.75, 1.0]:
                caplet_vols[t] = max(vol_1y, 1.0)
        except:
            for t in [0.25, 0.5, 0.75, 1.0]:
                caplet_vols[t] = max(cumulative_leg_prems[1.0] * 1.58, 1.0)

    # Step 2: initial guesses for anchors
    anchor_mats = sorted([m for m in cumulative_leg_prems if m > 1.0])
    for m in anchor_mats:
        caplet_vols[m] = caplet_vols.get(1.0, 75.0)

    # Step 3: simultaneous solve
    def price_with_interp(anchor_vols_array):
        from scipy.interpolate import CubicSpline
        temp_vols = dict(caplet_vols)
        for i, m in enumerate(anchor_mats):
            temp_vols[m] = max(anchor_vols_array[i], 1.0)
        all_mats = np.array(sorted([m for m in temp_vols if m >= 1.0 and m == int(m)]))
        all_vs   = np.array([temp_vols[m] for m in all_mats])
        cs = CubicSpline(all_mats, all_vs)
        interp = {}
        for t in [0.25, 0.5, 0.75, 1.0]:
            interp[t] = temp_vols.get(t, temp_vols.get(1.0, 75.0))
        t = 1.25
        while t <= all_mats[-1] + 1e-6:
            interp[round(t, 2)] = max(float(cs(t)), 1.0)
            t += 0.25
        errors = []
        for m in anchor_mats:
            errors.append(price_caplets_with_vol_curve(ccy, m, interp, notional_mm=1.0) - cumulative_leg_prems[m])
        return np.array(errors)

    if anchor_mats:
        from scipy.optimize import least_squares
        try:
            res = least_squares(price_with_interp, [caplet_vols[m] for m in anchor_mats],
                                ftol=1e-4, xtol=1e-4, gtol=1e-4, max_nfev=200)
            if res.success:
                for i, m in enumerate(anchor_mats):
                    caplet_vols[m] = max(res.x[i], 1.0)
        except:
            pass

    # Final interpolation
    from scipy.interpolate import CubicSpline
    anch = np.array(sorted([m for m in caplet_vols if m >= 1.0 and m == int(m)]))
    if len(anch) < 2:
        return caplet_vols
    cs = CubicSpline(anch, [caplet_vols[m] for m in anch])
    final = {}
    for t in [0.25, 0.5, 0.75, 1.0]:
        final[t] = caplet_vols.get(t, caplet_vols.get(1.0, 75.0))
    t = 1.25
    while t <= anch[-1] + 1e-6:
        final[round(t, 2)] = max(float(cs(t)), 1.0)
        t += 0.25
    return final


# ═══════════════════════════════════════════════════════════════════════
# SR3-driven Caplet Vol Curve builders (Step 5 — CFS pricer read-side)
# ═══════════════════════════════════════════════════════════════════════
# Three vol source modes for USD CFS:
#   "otc"       — existing wedge-based OTC path (default, unchanged)
#   "sr3_hybrid"— listed SR3 wins 0→cutoff_y, OTC wedges handle > cutoff_y
#   "sr3_full"  — listed SR3 everywhere it exists (diagnostic/debug)
# These coexist — curves can be built in parallel and overlaid for comparison.


def _load_sr3_latest_usd() -> dict:
    """Load latest USD SR3 snapshot as {contract_code: row_dict}. Cached per-session."""
    try:
        snaps = list_sr3_snapshots("USD", limit=1)
        if not snaps:
            return {}
        return load_sr3_snapshot(currency="USD")
    except Exception:
        return {}


def _load_sr3_latest_usd_with_session_edits() -> dict:
    """
    Load latest USD SR3 snapshot and overlay CFS-tab session edits on top.
    Session edits are stored in st.session_state['_cfs_listed_session_edits']
    as {contract_code: {mode, ratio, bp}}. Non-destructive — DB values unchanged
    until the user clicks "Save to snapshot" on the CFS tab.

    v2204k: This is the EDITOR-DISPLAY variant — uses working (uncommitted) edits
    so the editor shows the user's current typing. For PRICING, use
    _load_sr3_latest_usd_with_committed_edits() instead which uses the snapshot
    the user has explicitly committed via the "✓ Commit Listed Vols" button.
    """
    rows = _load_sr3_latest_usd()
    if not rows:
        return rows
    session_edits = st.session_state.get("_cfs_listed_session_edits", {}) or {}
    for code, edits in session_edits.items():
        if code not in rows:
            continue
        if "listed_adj_mode" in edits:
            rows[code]["listed_adj_mode"] = edits["listed_adj_mode"]
        if "listed_adj_ratio" in edits:
            rows[code]["listed_adj_ratio"] = edits["listed_adj_ratio"]
        if "listed_adj_bp" in edits:
            rows[code]["listed_adj_bp"] = edits["listed_adj_bp"]
    return rows


def _load_sr3_latest_usd_with_committed_edits() -> dict:
    """
    Load latest USD SR3 snapshot and overlay ONLY COMMITTED edits on top.
    Committed edits are stored in st.session_state['_cfs_listed_committed_edits']
    as {contract_code: {mode, ratio, bp}} — populated when the user clicks
    "✓ Commit Listed Vols" on the CFS tab. This is what the pricer / caplet
    builder reads so that casual ratio typing in the editor does NOT trigger
    a recompute storm on every keystroke.
    """
    rows = _load_sr3_latest_usd()
    if not rows:
        return rows
    committed = st.session_state.get("_cfs_listed_committed_edits", {}) or {}
    for code, edits in committed.items():
        if code not in rows:
            continue
        if "listed_adj_mode" in edits:
            rows[code]["listed_adj_mode"] = edits["listed_adj_mode"]
        if "listed_adj_ratio" in edits:
            rows[code]["listed_adj_ratio"] = edits["listed_adj_ratio"]
        if "listed_adj_bp" in edits:
            rows[code]["listed_adj_bp"] = edits["listed_adj_bp"]
    return rows


def _apply_listed_adjustment(atm_vol, row: dict) -> float:
    """
    Apply the per-contract listed-to-delivered adjustment.
    row is an sr3_vol_history row_dict with listed_adj_mode/ratio/bp fields.
    Returns delivered vol in bp.
    
    Mode 'ratio': delivered = atm × ratio  (default ratio = 1.0 → no change)
    Mode 'bp':    delivered = atm + bp     (default bp    = 0.0 → no change)
    """
    if atm_vol is None:
        return None
    mode = (row.get("listed_adj_mode") or "ratio").lower()
    if mode == "bp":
        bp = float(row.get("listed_adj_bp") or 0.0)
        return float(atm_vol) + bp
    # default / ratio
    ratio = float(row.get("listed_adj_ratio") or 1.0)
    return float(atm_vol) * ratio


def _sr3_anchor_points(sr3_rows: dict, today=None, apply_adjustment: bool = True) -> list:
    """
    Extract (T_yrs, vol_bp) anchor points for CFS caplet curve.
    
    apply_adjustment=True (default): returns delivered vol = listed * ratio (or + bp).
        Used by Listed bootstrap which treats delivered as the caplet vol.
    apply_adjustment=False: returns RAW listed ATM vol with no adjustment.
        Used by SR3 hybrid / SR3 full — these display the listed surface as-is.
    
    CRITICAL: The vol of an SR3 option is on the 3M SOFR fixing that occurs
    in the underlying future's reference period. The caplet being priced at
    T_caplet_fix has its fixing at T_caplet_fix. The correct anchor for SFRM6
    (option expires 12-Jun-26, underlying is SFRM6 future referencing Jun→Sep
    3M SOFR) is the MIDPOINT of that Jun→Sep reference period (~T=0.5y for
    today=19-Apr-26), NOT the option's expiry (~T=0.15y).
    
    Returns list sorted by T. Mid-curves skipped (forward-start rate vols,
    handled via a separate path).
    """
    from datetime import date as _d
    if today is None:
        today = _d.today()
    anchors = []
    for code, row in (sr3_rows or {}).items():
        ctype = row.get("contract_type", "")
        if "MC" in ctype:
            continue
        atm = row.get("atm_vol")
        if atm is None:
            continue
        ed = row.get("expiry_date")
        md = row.get("maturity_date")
        if ed is None:
            continue
        try:
            ed_d = ed if hasattr(ed, "toordinal") else _d.fromisoformat(str(ed)[:10])
            if md is not None:
                md_d = md if hasattr(md, "toordinal") else _d.fromisoformat(str(md)[:10])
            else:
                from datetime import timedelta as _td
                md_d = ed_d + _td(days=90)
            from datetime import timedelta as _td2
            mid = ed_d + _td2(days=(md_d - ed_d).days // 2)
            t = (mid - today).days / 365.25
        except Exception:
            continue
        if t <= 0:
            continue
        if apply_adjustment:
            vol = _apply_listed_adjustment(atm, row)
        else:
            vol = float(atm)
        if vol is None or vol <= 0:
            continue
        anchors.append((t, vol))
    anchors.sort(key=lambda x: x[0])
    return anchors


def _build_listed_caplet_curve_by_date(
    sr3_rows: dict,
    whites_selected: set,
    strip_expiry_y: float,
    strip_tenor_y: float,
    today=None,
    apply_adjustment: bool = True,
) -> dict | None:
    """
    Build a caplet vol curve for a CFS strip by mapping each caplet fixing date
    to the CLOSEST selected white contract's expiry. This is the correct
    approach for pricing CFS caps off listed vols — each caplet gets the vol
    of the listed option whose expiry is nearest its fixing date, rather than
    a T-midpoint PCHIP interpolation (which mis-maps contracts to the wrong
    fixings and produces vols too high for the 1Y strip).
    
    strip_expiry_y: forward start of the cap (e.g. 0.25 for 3m start)
    strip_tenor_y: cap length (e.g. 1.0 for 1Y cap)
    whites_selected: set of contract codes (e.g. {"SFRM6", "SFRU6", "SFRZ6", "SFRH7"})
    apply_adjustment: if True, use delivered vol (listed*ratio or listed+bp). Listed bootstrap passes True.
    
    Returns {T_fix_y: vol_bp} dict. Caller PCHIPs this to quarterly grid if needed.
    """
    from datetime import date as _d, timedelta as _td
    if today is None:
        today = _d.today()
    if not sr3_rows or not whites_selected:
        return None
    # Get selected whites with their expiry dates
    white_expiry = []
    for code in whites_selected:
        row = sr3_rows.get(code)
        if not row:
            continue
        ed = row.get("expiry_date")
        atm = row.get("atm_vol")
        if ed is None or atm is None:
            continue
        try:
            ed_d = ed if hasattr(ed, "toordinal") else _d.fromisoformat(str(ed)[:10])
        except Exception:
            continue
        if apply_adjustment:
            vol = _apply_listed_adjustment(atm, row)
        else:
            vol = float(atm)
        if vol is None or vol <= 0:
            continue
        white_expiry.append((code, ed_d, float(vol)))
    if not white_expiry:
        return None
    # Build caplet fixing schedule for the strip (same logic as
    # price_caplets_with_vol_curve): quarterly from strip_expiry_y to
    # strip_expiry_y+strip_tenor_y, FIRST FIXING SKIPPED.
    # For each caplet, we record BOTH the accrual end (T_fix, the key in
    # caplet_vol_dict) and the accrual start (T_start, the date used to
    # find the closest SR3 contract).
    cap_start = strip_expiry_y if strip_expiry_y > 0 else 1.0 / 252.0
    cap_end = cap_start + strip_tenor_y
    caplet_pairs = []  # list of (T_start, T_fix)
    t = cap_start
    while t < cap_end - 1e-8:
        t_next = min(t + 0.25, cap_end)
        caplet_pairs.append((t, round(t_next, 4)))
        t = t_next
    # Skip first fixing (forward rate is known)
    caplet_pairs = caplet_pairs[1:] if len(caplet_pairs) > 1 else caplet_pairs
    # For each caplet, match by accrual START date to the closest white expiry.
    # (e.g. 3m→6m caplet's START is 3m from today; closest white to "3m from
    # today" is SFRM6 for whites starting 20-Apr-26.)
    result = {}
    for T_start, T_fix in caplet_pairs:
        match_date = today + _td(days=int(round(T_start * 365.25)))
        best = min(white_expiry, key=lambda w: abs((w[1] - match_date).days))
        result[T_fix] = best[2]
    return result


def build_caplet_vol_curve_sr3(
    ccy: str,
    cutoff_years: float = 2.0,
    otc_fallback_curve: dict | None = None,
    final_maturity_y: float = 10.0,
    apply_adjustment: bool = False,
) -> dict | None:
    """
    Build a caplet vol curve using LISTED SR3 vols for maturities ≤ cutoff_years,
    and falling back to the OTC-derived curve for maturities > cutoff_years.
    
    apply_adjustment=False (default): uses RAW listed ATM vols.
    apply_adjustment=True: uses delivered vols (listed * ratio or listed + bp).
    
    Returns {T_yrs: vol_bp} at quarterly steps from 0.25 out to final_maturity_y.
    
    Only USD is supported — AUD/NZD/EUR fall through to otc_fallback_curve.
    """
    if ccy != "USD":
        return otc_fallback_curve
    
    sr3_rows = _load_sr3_latest_usd_with_committed_edits()
    if not sr3_rows:
        return otc_fallback_curve
    
    anchors = _sr3_anchor_points(sr3_rows, apply_adjustment=apply_adjustment)
    if not anchors:
        return otc_fallback_curve
    
    # Build interpolator over SR3 anchors (up to cutoff)
    anchors_below_cutoff = [(t, v) for t, v in anchors if t <= cutoff_years + 0.01]
    if len(anchors_below_cutoff) < 2:
        # Need at least 2 points for interpolation
        return otc_fallback_curve
    
    from scipy.interpolate import PchipInterpolator
    anch_t = np.array([t for t, _ in anchors_below_cutoff])
    anch_v = np.array([v for _, v in anchors_below_cutoff])
    
    # Handle T outside anchor range with directional fallback
    first_t, first_v = anchors_below_cutoff[0]
    last_t,  last_v  = anchors_below_cutoff[-1]
    
    pchip = PchipInterpolator(anch_t, anch_v, extrapolate=False)
    
    curve = {}
    t = 0.25
    while t <= final_maturity_y + 1e-6:
        t_r = round(t, 2)
        if t <= cutoff_years + 0.01:
            if t <= first_t:
                curve[t_r] = first_v   # flat extrapolate below first anchor
            elif t >= last_t:
                curve[t_r] = last_v    # flat extrapolate above last anchor (into gap before cutoff)
            else:
                v = pchip(t)
                if np.isnan(v):
                    # In-range NaN shouldn't happen, but be safe
                    curve[t_r] = last_v if t > (first_t + last_t)/2 else first_v
                else:
                    curve[t_r] = float(v)
        else:
            # Beyond cutoff — use OTC fallback
            if otc_fallback_curve:
                # Find nearest OTC point
                otc_keys = sorted(otc_fallback_curve.keys())
                if t_r in otc_fallback_curve:
                    curve[t_r] = otc_fallback_curve[t_r]
                else:
                    # Linear interp or nearest
                    below = [k for k in otc_keys if k <= t_r]
                    above = [k for k in otc_keys if k >= t_r]
                    if below and above:
                        lo, hi = below[-1], above[0]
                        if lo == hi:
                            curve[t_r] = otc_fallback_curve[lo]
                        else:
                            w = (t_r - lo) / (hi - lo)
                            curve[t_r] = (1 - w) * otc_fallback_curve[lo] + w * otc_fallback_curve[hi]
                    elif below:
                        curve[t_r] = otc_fallback_curve[below[-1]]
                    elif above:
                        curve[t_r] = otc_fallback_curve[above[0]]
                    else:
                        curve[t_r] = anch_v[-1]  # last SR3 anchor
            else:
                curve[t_r] = anch_v[-1]  # flat extend last SR3 point
        t += 0.25
    return curve


def build_caplet_vol_curve_sr3_full(
    ccy: str,
    otc_fallback_curve: dict | None = None,
    final_maturity_y: float = 10.0,
    apply_adjustment: bool = False,
) -> dict | None:
    """
    Diagnostic mode: use ALL SR3 anchor points (standards/serials/quarterlies
    up to whatever liquidity exists, typically Gold ~4y). OTC fallback beyond.
    
    apply_adjustment=False (default): uses RAW listed ATM vols.
    apply_adjustment=True: uses delivered vols.
    """
    if ccy != "USD":
        return otc_fallback_curve
    sr3_rows = _load_sr3_latest_usd_with_committed_edits()
    if not sr3_rows:
        return otc_fallback_curve
    anchors = _sr3_anchor_points(sr3_rows, apply_adjustment=apply_adjustment)
    if len(anchors) < 2:
        return otc_fallback_curve
    
    from scipy.interpolate import PchipInterpolator
    anch_t = np.array([t for t, _ in anchors])
    anch_v = np.array([v for _, v in anchors])
    
    # SR3 covers up to last anchor; beyond that use OTC
    sr3_max_t = anch_t[-1]
    first_t, first_v = anchors[0]
    last_t,  last_v  = anchors[-1]
    
    pchip = PchipInterpolator(anch_t, anch_v, extrapolate=False)
    
    curve = {}
    t = 0.25
    while t <= final_maturity_y + 1e-6:
        t_r = round(t, 2)
        if t <= sr3_max_t + 0.01:
            if t <= first_t:
                curve[t_r] = first_v
            elif t >= last_t:
                curve[t_r] = last_v
            else:
                v = pchip(t)
                if np.isnan(v):
                    curve[t_r] = last_v if t > (first_t + last_t)/2 else first_v
                else:
                    curve[t_r] = float(v)
        else:
            if otc_fallback_curve:
                otc_keys = sorted(otc_fallback_curve.keys())
                below = [k for k in otc_keys if k <= t_r]
                above = [k for k in otc_keys if k >= t_r]
                if t_r in otc_fallback_curve:
                    curve[t_r] = otc_fallback_curve[t_r]
                elif below and above:
                    lo, hi = below[-1], above[0]
                    if lo == hi:
                        curve[t_r] = otc_fallback_curve[lo]
                    else:
                        w = (t_r - lo) / (hi - lo)
                        curve[t_r] = (1 - w) * otc_fallback_curve[lo] + w * otc_fallback_curve[hi]
                elif below:
                    curve[t_r] = otc_fallback_curve[below[-1]]
                else:
                    curve[t_r] = anch_v[-1]
            else:
                curve[t_r] = anch_v[-1]
        t += 0.25
    return curve


def build_caplet_vol_curve(ccy: str, atm_surface, sabr_params=None, 
                          spread_3m1y=-3.0, spread_1y1y=12.0, spread_2y1y=15.0, 
                          spread_3y1y=19.0, spread_4y1y=22.0, spread_5y2y=40.0, spread_7y3y=60.0,
                          spread_10y2y=50.0, spread_12y3y=70.0):
    """
    Build caplet vol curve using cumulative premium method with proper solving.
    """
    if atm_surface is None or atm_surface.empty:
        return None
    
    import scipy.optimize as opt
    
    caplet_vols = {}
    cumulative_leg_prems = {}
    
    def get_swaption_premium(expiry_label, tenor_y):
        """Get swaption PREMIUM - calculate directly from vol surface"""
        try:
            # Get curve and vol
            _cc = st.session_state.get("config_curves", {}).get(ccy)
            curve = _cc if _cc is not None else get_ccy_curve(ccy)
            _ois_cb = st.session_state.get("config_basis", {}).get(ccy, {}).get("ois")
            ois_curve = _ois_cb if _ois_cb is not None else get_basis_curve(ccy, "ois")
            if atm_surface is None or curve is None:
                return None
            
            vol_bp = get_matrix_value(atm_surface, expiry_label, tenor_y)
            if vol_bp is None:
                return None
            
            # Read directly from atm_prem_matrix — same number as Curves tab
            _pm = st.session_state.get("atm_prem_matrix", {}).get(ccy, {}).get("prem")
            if _pm is not None and not _pm.empty:
                v = get_matrix_value(_pm, expiry_label, tenor_y)
                if v is not None:
                    return float(v)
            # Fallback
            exp_y = label_to_years(expiry_label)
            _, ann, _ = forward_and_annuity_from_curve(curve, ccy, exp_y, tenor_y, None)
            sigma_n = vol_bp / 10000.0
            return 2 * 0.3989 * sigma_n * math.sqrt(max(exp_y,0.001)) * ann * 10000
        except:
            return None
    
    def price_caplets_flat_vol(vol_bp, final_maturity_y):
        """
        Price caplets using flat vol.
        Returns total LEG premium in bp.
        """
        flat_curve = {}
        t = 0.25
        while t <= final_maturity_y + 1e-6:
            flat_curve[round(t, 2)] = vol_bp
            t += 0.25
        return price_caplets_with_vol_curve(ccy, final_maturity_y, flat_curve, notional_mm=1.0)
    
    # === STEP 1: 1Y CFS ===
    # 1Y CFS = 3m start to 1Y maturity = 9 months = 3 quarterly fixings
    # Get EXACT CFS straddle from table OR calculate directly
    table_data_1y = st.session_state.get("cfs_table_data", {}).get("3m1y", {})
    cfs_1y_straddle = table_data_1y.get("cfs_straddle", None)
    
    if cfs_1y_straddle is None or cfs_1y_straddle <= 0:
        # Calculate directly: swaption premium + spread
        swaption_1y_straddle = get_swaption_premium("3m", 1.0)
        if swaption_1y_straddle is not None:
            cfs_1y_straddle = swaption_1y_straddle + spread_3m1y
    
    if cfs_1y_straddle and cfs_1y_straddle > 0:
        cfs_1y_leg = cfs_1y_straddle / 2.0
        cumulative_leg_prems[1.0] = cfs_1y_leg
        
        # Solve for FLAT vol to 1Y
        def objective_1y(vol_bp):
            return price_caplets_flat_vol(vol_bp, 1.0) - cfs_1y_leg
        
        try:
            vol_1y = opt.brentq(objective_1y, 1.0, 200.0, xtol=0.001)
            # Store flat vol at quarterly points for final interpolation
            for t in [0.25, 0.5, 0.75, 1.0]:
                caplet_vols[t] = max(vol_1y, 1.0)
        except:
            vol_fallback = max(cfs_1y_leg * 1.58, 1.0)
            for t in [0.25, 0.5, 0.75, 1.0]:
                caplet_vols[t] = vol_fallback
    
    # === STEP 2: BOOTSTRAP EACH 1Y GAP SEPARATELY ===
    # Helper: price ONLY caplets in a specific gap
    def price_gap_caplets(vol_bp, gap_start_y, gap_end_y):
        """
        Price ONLY the caplets from gap_start_y to gap_end_y using flat vol.
        Returns premium in bp contributed by this gap.
        """
        _cc = st.session_state.get("config_curves", {}).get(ccy)
        curve = _cc if _cc is not None else get_ccy_curve(ccy)
        _ois_cb = st.session_state.get("config_basis", {}).get(ccy, {}).get("ois")
        ois_curve = _ois_cb if _ois_cb is not None else get_basis_curve(ccy, "ois")
        if ois_curve is None:
            ois_curve = curve
        
        # Build schedule for the GAP only
        swap_start = 0.0 + 1.0 / 252.0
        gap_start_abs = swap_start + gap_start_y
        gap_end_abs = swap_start + gap_end_y
        
        sched = []
        t = gap_start_abs
        while t < gap_end_abs - 1e-8:
            t_next = min(t + 0.25, gap_end_abs)
            accrual = t_next - t
            # Store relative time from today for T_fix
            T_fix = t_next
            sched.append((T_fix, accrual))
            t = t_next
        
        sigma = vol_bp / 10000.0
        total_prem_dollars = 0.0
        
        for T_fix, accrual in sched:
            df = df_from_curve(ois_curve, T_fix)
            phi_zero = 1.0 / math.sqrt(2.0 * math.pi)
            price_rate = sigma * math.sqrt(T_fix) * phi_zero
            pv_dollars = 1e6 * accrual * df * price_rate
            total_prem_dollars += pv_dollars
        
        return (total_prem_dollars / 1e6) * 10000.0
    
    wedges = [
        ("1y1y", "1y", 1.0, spread_1y1y, 2.0, 1.0),
        ("2y1y", "2y", 1.0, spread_2y1y, 3.0, 2.0),
        ("3y1y", "3y", 1.0, spread_3y1y, 4.0, 3.0),
        ("4y1y", "4y", 1.0, spread_4y1y, 5.0, 4.0),
        ("5y2y", "5y", 2.0, spread_5y2y, 7.0, 5.0),
        ("7y3y", "7y", 3.0, spread_7y3y, 10.0, 7.0),
        ("10y2y", "10y", 2.0, spread_10y2y, 12.0, 10.0),
        ("12y3y", "12y", 3.0, spread_12y3y, 15.0, 12.0),
    ]
    
    for table_label, expiry, tenor, spread, result_mat, prior_mat in wedges:
        if prior_mat not in cumulative_leg_prems:
            continue
        
        wedge_data = st.session_state.get("cfs_table_data", {}).get(table_label, {})
        wedge_straddle = wedge_data.get("cfs_straddle", None)
        
        if wedge_straddle is None or wedge_straddle <= 0:
            wedge_swaption_straddle = get_swaption_premium(expiry, tenor)
            if wedge_swaption_straddle is not None:
                wedge_straddle = wedge_swaption_straddle + spread
        
        if wedge_straddle is None or wedge_straddle <= 0:
            continue
        
        wedge_leg = wedge_straddle / 2.0
        
        # This wedge_leg is the INCREMENTAL premium for the gap (prior_mat to result_mat)
        gap_premium_target = wedge_leg
        
        # Bootstrap: find flat vol for THIS GAP ONLY
        def objective(vol_bp):
            return price_gap_caplets(vol_bp, prior_mat, result_mat) - gap_premium_target
        
        wedge_leg = wedge_straddle / 2.0
        cumulative_leg_prem = cumulative_leg_prems[prior_mat] + wedge_leg
        cumulative_leg_prems[result_mat] = cumulative_leg_prem
        
        # Store initial guess for anchor vol (will be refined later)
        gap_premium = wedge_leg
        initial_vol_guess = max(gap_premium * 1.5, 50.0)
        caplet_vols[result_mat] = initial_vol_guess
    
    # === STEP 3: SOLVE FOR ALL ANCHOR VOLS SIMULTANEOUSLY ===
    # Must solve all at once because cubic spline shape depends on ALL anchors
    
    def price_with_interp_curve(anchor_vols_array):
        """
        Given vols at anchor points, cubic spline interpolate and price all maturities.
        Returns array of pricing errors vs targets.
        """
        # Build vol dict from array
        temp_vols = dict(caplet_vols)  # Start with 1Y vols
        anchor_mats_to_solve = sorted([m for m in cumulative_leg_prems.keys() if m > 1.0])
        
        for i, mat in enumerate(anchor_mats_to_solve):
            temp_vols[mat] = max(anchor_vols_array[i], 1.0)
        
        # Cubic spline - only use integer anchors
        from scipy.interpolate import CubicSpline
        all_anchor_mats = np.array(sorted([m for m in temp_vols.keys() if m >= 1.0 and m == int(m)]))
        all_anchor_vols = np.array([temp_vols[m] for m in all_anchor_mats])
        
        cs = CubicSpline(all_anchor_mats, all_anchor_vols)
        
        # Build interpolated curve
        interp_curve = {}
        for t in [0.25, 0.5, 0.75, 1.0]:
            interp_curve[t] = temp_vols.get(t, temp_vols.get(1.0, 75.0))
        
        t = 1.25
        max_mat = all_anchor_mats[-1]
        while t <= max_mat + 1e-6:
            interp_curve[round(t, 2)] = max(float(cs(t)), 1.0)
            t += 0.25
        
        # Price each maturity using SHARED pricing function
        errors = []
        for check_mat in anchor_mats_to_solve:
            target_prem = cumulative_leg_prems[check_mat]
            actual_prem = price_caplets_with_vol_curve(ccy, check_mat, interp_curve, notional_mm=1.0)
            errors.append(actual_prem - target_prem)
        
        return np.array(errors)
    
    # Solve for all anchor vols simultaneously
    anchor_mats_to_solve = sorted([m for m in cumulative_leg_prems.keys() if m > 1.0])
    
    if len(anchor_mats_to_solve) > 0:
        initial_guess = np.array([caplet_vols[m] for m in anchor_mats_to_solve])
        
        from scipy.optimize import least_squares
        try:
            result = least_squares(price_with_interp_curve, initial_guess,
                                   ftol=1e-4, xtol=1e-4, gtol=1e-4,
                                   max_nfev=200)
            
            if result.success:
                for i, mat in enumerate(anchor_mats_to_solve):
                    caplet_vols[mat] = max(result.x[i], 1.0)
        except:
            pass
    
    # Final cubic spline interpolation with solved anchors
    from scipy.interpolate import CubicSpline
    anchor_mats = np.array(sorted([m for m in caplet_vols.keys() if m >= 1.0 and m == int(m)]))
    anchor_vols = np.array([caplet_vols[m] for m in anchor_mats])
    
    if len(anchor_mats) >= 2:
        cs = CubicSpline(anchor_mats, anchor_vols)
        
        caplet_vols_final = {}
        for t in [0.25, 0.5, 0.75, 1.0]:
            caplet_vols_final[t] = caplet_vols.get(t, caplet_vols.get(1.0, 75.0))
        
        t = 1.25
        max_mat = anchor_mats[-1]
        while t <= max_mat + 1e-6:
            caplet_vols_final[round(t, 2)] = max(float(cs(t)), 1.0)
            t += 0.25  # Caps are always quarterly
        
        return caplet_vols_final
    
    return caplet_vols if caplet_vols else None



def get_caplet_vol_for_fixing(caplet_curve, fixing_time_y):
    """
    Get caplet vol for a specific fixing time from the term structure.
    Uses linear interpolation if needed.
    """
    if caplet_curve is None or len(caplet_curve) == 0:
        return None
    
    # Exact match
    if fixing_time_y in caplet_curve:
        return caplet_curve[fixing_time_y]
    
    # Interpolate
    maturities = sorted(caplet_curve.keys())
    
    # Extrapolate flat before first point
    if fixing_time_y < maturities[0]:
        return caplet_curve[maturities[0]]
    
    # Extrapolate flat after last point
    if fixing_time_y > maturities[-1]:
        return caplet_curve[maturities[-1]]
    
    # Linear interpolation
    for i in range(len(maturities) - 1):
        t1, t2 = maturities[i], maturities[i + 1]
        if t1 <= fixing_time_y <= t2:
            v1, v2 = caplet_curve[t1], caplet_curve[t2]
            alpha = (fixing_time_y - t1) / (t2 - t1)
            return v1 + alpha * (v2 - v1)
    
    return caplet_curve[maturities[-1]]


