        if msgs:
            _cdebug = []
            def _mat_to_label(y):
                """Convert MaturityY float to human-readable tenor label."""
                days = y * 365.25
                if days < 10: return "1w"
                if days < 20: return "2w"
                m = round(y * 12)
                if m == 0: return "1w"
                if m == 1: return "1m"
                if m == 2: return "2m"
                if m == 3: return "3m"
                if m == 4: return "4m"
                if m == 5: return "5m"
                if m == 6: return "6m"
                if m == 9: return "9m"
                if m == 12: return "1y"
                if m == 18: return "18m"
                yr = round(y)
