def _load_curve_from_db_latest(floating_rate: str, ccy: str = "AUD", load_date: str = None) -> pd.DataFrame:
    """Load swap rates from swap_rates table. load_date: specific date or None for latest."""
    try:
        conn = get_db_connection()
        if conn is None:
            return None
        cur = conn.cursor()
        # Use specified date or find the most recent available
        if load_date:
            # Try exact date first, fall back to most recent on or before that date
            cur.execute(
                "SELECT MAX(date) FROM swap_rates WHERE currency=%s AND floating_rate=%s AND date <= %s",
                (ccy, floating_rate, load_date)
            )
        else:
            cur.execute(
                "SELECT MAX(date) FROM swap_rates WHERE currency=%s AND floating_rate=%s",
                (ccy, floating_rate)
            )
        row = cur.fetchone()
        if not row or row[0] is None:
            conn.close()
            return None
        latest_date = row[0]
        # Get all tenors for that date
        cur.execute(
            "SELECT tenor, rate FROM swap_rates WHERE currency=%s AND floating_rate=%s AND date=%s ORDER BY tenor",
            (ccy, floating_rate, latest_date)
        )
        rows = cur.fetchall()
        conn.close()
        if not rows:
            return None
        # Convert to MaturityY / ZeroRatePct format
        records = []
        for tenor, rate in rows:
            t = str(tenor).strip().upper()
            import re as _re
            m = _re.match(r"(\d+(?:\.\d+)?)(Y|M)", t)
            if not m: continue
            v, u = float(m.group(1)), m.group(2)
            mat_y = v if u == "Y" else v / 12
            records.append({"MaturityY": mat_y, "ZeroRatePct": float(rate)})  # Supabase stores as % (e.g. 4.78); ZeroRatePct in percent
        if not records:
            return None
        df = pd.DataFrame(records).sort_values("MaturityY").reset_index(drop=True)
        df["_source_date"] = str(latest_date)
        return df
    except Exception:
        return None


@st.cache_data(ttl=600, show_spinner=False)
def _load_ois_from_db_latest(ccy: str = "AUD") -> pd.DataFrame:
    """Load latest AONIA OIS swap rates from swap_rates table."""
    try:
        conn = get_db_connection()
        if conn is None:
            return None
        cur = conn.cursor()
        cur.execute(
            "SELECT MAX(date) FROM swap_rates WHERE currency=%s AND floating_rate=%s",
            (ccy, "AONIA")
        )
        row = cur.fetchone()
        if not row or row[0] is None:
            conn.close()
            return None
        latest_date = row[0]
        cur.execute(
            "SELECT tenor, rate FROM swap_rates WHERE currency=%s AND floating_rate=%s AND date=%s ORDER BY tenor",
            (ccy, "AONIA", latest_date)
        )
        rows = cur.fetchall()
        conn.close()
        if not rows:
            return None
        records = []
        for tenor, rate in rows:
            t = str(tenor).strip().upper()
            import re as _re
            m = _re.match(r"(\d+(?:\.\d+)?)(Y|M)", t)
            if not m: continue
            v, u = float(m.group(1)), m.group(2)
            mat_y = v if u == "Y" else v / 12
            records.append({"MaturityY": mat_y, "ZeroRatePct": float(rate)})  # Supabase stores as % (e.g. 4.78); ZeroRatePct in percent
        if not records:
            return None
        df = pd.DataFrame(records).sort_values("MaturityY").reset_index(drop=True)
        df["_source_date"] = str(latest_date)
        return df
    except Exception:
        return None


def generate_forward_matrix(ccy: str, curve: pd.DataFrame, basis_6v3: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    """Public wrapper   —   converts DataFrames → tuples and calls the cached matrix generator."""
    if curve is None or curve.empty:
        return pd.DataFrame()
    curve_tuple = (
        tuple(curve["MaturityY"].to_numpy().astype(float).tolist()),
        tuple(curve["ZeroRatePct"].to_numpy().astype(float).tolist()),
    )
    basis_tuple = None
    if basis_6v3 is not None and not basis_6v3.empty and "MaturityY" in basis_6v3.columns and "BasisBp" in basis_6v3.columns:
        basis_tuple = (
            tuple(basis_6v3["MaturityY"].to_numpy().astype(float).tolist()),
            tuple(basis_6v3["BasisBp"].to_numpy().astype(float).tolist()),
        )
    return _generate_forward_matrix_cached(ccy, curve_tuple, basis_tuple, convention="market", ois_tuple=None)


def generate_forward_matrix_convention(ccy: str, curve: pd.DataFrame, basis_6v3: Optional[pd.DataFrame] = None,
                                        convention: str = "market") -> pd.DataFrame:
    """Public wrapper   —   like generate_forward_matrix but with explicit convention override."""
    if curve is None or curve.empty:
        return pd.DataFrame()
    curve_tuple = (
        tuple(curve["MaturityY"].to_numpy().astype(float).tolist()),
        tuple(curve["ZeroRatePct"].to_numpy().astype(float).tolist()),
    )
    basis_tuple = None
    if basis_6v3 is not None and not basis_6v3.empty and "MaturityY" in basis_6v3.columns and "BasisBp" in basis_6v3.columns:
        basis_tuple = (
            tuple(basis_6v3["MaturityY"].to_numpy().astype(float).tolist()),
            tuple(basis_6v3["BasisBp"].to_numpy().astype(float).tolist()),
        )
    return _generate_forward_matrix_cached(ccy, curve_tuple, basis_tuple, convention=convention, ois_tuple=None)


@st.fragment
def curves_tab():
    import plotly.graph_objects as go
    st.subheader("📐 IRS Curves & Forward Matrix")

    ccy = st.session_state.get("sidebar_ccy", "AUD")
    if ccy not in SUPPORTED_CURRENCIES: ccy = SUPPORTED_CURRENCIES[0]

    curve     = st.session_state.get("config_curves", {}).get(ccy)
    basis_6v3 = st.session_state.get("config_basis", {}).get(ccy, {}).get("6v3")
    basis_3v1 = st.session_state.get("config_basis", {}).get(ccy, {}).get("3v1")
    ois_curve = st.session_state.get("config_basis", {}).get(ccy, {}).get("ois")
    par_rates = st.session_state.get("_irs_par_rates", {}).get(ccy)

    if curve is None:
        st.info("No curves loaded. Go to IRS / Vol Upload tab and commit your config file.")
        return


    def _clean(df):
        if df is None: return None
        return df.drop(columns=["_source_date"], errors="ignore")

    curve_c = _clean(curve)
    b6c     = _clean(basis_6v3)
    b3c     = _clean(basis_3v1)
    oisc    = _clean(ois_curve)

    # ══════════════════════════════════════════════════════════════════════════
    # USD CURVES — SOFR OIS / FF OIS / FF-SOFR BASIS
    # ══════════════════════════════════════════════════════════════════════════
    if ccy == "USD":
        import plotly.graph_objects as go
        _sofr_curve  = st.session_state.get("config_curves", {}).get("USD")
        _ff_ois      = st.session_state.get("config_basis", {}).get("USD", {}).get("fedfunds_ois")
        _sofr_ff_bas = st.session_state.get("config_basis", {}).get("USD", {}).get("sofr_ff_basis")

        if _sofr_curve is None:
            st.info("No USD curves loaded. Go to IRS / Vol Upload tab and commit your config file.")
        else:
            # ── USD Curve Chart ──────────────────────────────────────────────
            _usd_fig = go.Figure()

            # SOFR swap curve
            if _sofr_curve is not None and not _sofr_curve.empty:
                _usd_fig.add_trace(go.Scatter(
                    x=_sofr_curve["MaturityY"], y=_sofr_curve["ZeroRatePct"],
                    mode="lines+markers", name="SOFR Swap",
                    line=dict(color="#38bdf8", width=2),
                    marker=dict(size=5)
                ))

            # FF OIS curve
            if _ff_ois is not None and not _ff_ois.empty:
                _usd_fig.add_trace(go.Scatter(
                    x=_ff_ois["MaturityY"], y=_ff_ois["ZeroRatePct"],
                    mode="lines+markers", name="FF OIS",
                    line=dict(color="#f59e0b", width=2, dash="dash"),
                    marker=dict(size=5)
                ))

            _usd_fig.update_layout(
                title="USD Rate Curves (%)", height=320, margin=dict(l=40,r=20,t=40,b=40),
                paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(15,23,42,0.8)",
                font=dict(color="#94a3b8", size=11),
                xaxis=dict(title="Maturity (Y)", gridcolor="#1e293b"),
                yaxis=dict(title="Rate (%)", gridcolor="#1e293b"),
                legend=dict(bgcolor="rgba(0,0,0,0)"),
                hovermode="x unified"
            )
            st.plotly_chart(_usd_fig, use_container_width=True)

            # USD Curve Data Table
            # Helper: convert maturity (years) → tenor label for DISPLAY only
            def _mat_to_tenor(_y):
                try:
                    _y = float(_y)
                except Exception:
                    return str(_y)
                _map = [
                    (1/52, "1w"), (2/52, "2w"), (3/52, "3w"),
                    (1/12, "1m"), (2/12, "2m"), (3/12, "3m"), (4/12, "4m"),
                    (5/12, "5m"), (6/12, "6m"), (7/12, "7m"), (8/12, "8m"),
                    (9/12, "9m"), (10/12, "10m"), (11/12, "11m"),
                    (1.0, "1y"), (1.5, "18m"),
                    (2.0, "2y"), (3.0, "3y"), (4.0, "4y"), (5.0, "5y"),
                    (6.0, "6y"), (7.0, "7y"), (8.0, "8y"), (9.0, "9y"),
                    (10.0, "10y"), (12.0, "12y"), (15.0, "15y"),
                    (20.0, "20y"), (25.0, "25y"), (30.0, "30y"),
                    (40.0, "40y"), (50.0, "50y"),
                ]
                for _v, _lbl in _map:
                    if abs(_y - _v) < 0.005:
                        return _lbl
                return f"{_y:.4g}Y"

            def _relabel_maturity(_df):
                """Return display copy with MaturityY mapped to tenor labels. Original untouched."""
                if _df is None or _df.empty:
                    return _df
                _dc = _df.copy()
                if "MaturityY" in _dc.columns:
                    _dc["MaturityY"] = _dc["MaturityY"].apply(_mat_to_tenor)
                return _dc

            with st.expander("USD Curve Data", expanded=True):
                _usd_tcols = st.columns(3)
                with _usd_tcols[0]:
                    st.caption("SOFR Swap (%)")
                    if _sofr_curve is not None and not _sofr_curve.empty:
                        st.dataframe(_relabel_maturity(_sofr_curve).rename(columns={"MaturityY":"Tenor","ZeroRatePct":"Rate(%)"}), use_container_width=True, hide_index=True)
                with _usd_tcols[1]:
                    st.caption("FF OIS (%)")
                    if _ff_ois is not None and not _ff_ois.empty:
                        st.dataframe(_relabel_maturity(_ff_ois).rename(columns={"MaturityY":"Tenor","ZeroRatePct":"Rate(%)"}), use_container_width=True, hide_index=True)
                with _usd_tcols[2]:
                    st.caption("SOFR-FF Basis (bp)")
                    if _sofr_ff_bas is not None and not _sofr_ff_bas.empty:
                        st.dataframe(_relabel_maturity(_sofr_ff_bas).rename(columns={"MaturityY":"Tenor","BasisBp":"Basis(bp)"}), use_container_width=True, hide_index=True)

            # SOFR-FF Basis chart (bp, separate axis)
            if _sofr_ff_bas is not None and not _sofr_ff_bas.empty:
                _bas_fig = go.Figure()
                _bas_fig.add_trace(go.Bar(
                    x=_sofr_ff_bas["MaturityY"], y=_sofr_ff_bas["BasisBp"],
                    name="SOFR-FF Basis",
                    marker_color=["#22c55e" if v >= 0 else "#ef4444" for v in _sofr_ff_bas["BasisBp"]]
                ))
                _bas_fig.update_layout(
                    title="SOFR / FF Basis (bp)", height=220, margin=dict(l=40,r=20,t=40,b=40),
                    paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(15,23,42,0.8)",
                    font=dict(color="#94a3b8", size=11),
                    xaxis=dict(title="Maturity (Y)", gridcolor="#1e293b"),
                    yaxis=dict(title="Basis (bp)", gridcolor="#1e293b"),
                )
                st.plotly_chart(_bas_fig, use_container_width=True)

            st.markdown("---")

            # ── USD Forward Matrix ───────────────────────────────────────────
            if "usd_fwd_matrix" not in st.session_state: st.session_state["usd_fwd_matrix"] = {}
            if "usd_fwd_section_open" not in st.session_state: st.session_state["usd_fwd_section_open"] = True

            _ufl = "▼ Hide USD Forward Matrix" if st.session_state["usd_fwd_section_open"] else "▶ Show USD Forward Matrix"
            if st.button(_ufl, key="usd_fwd_toggle"):
                st.session_state["usd_fwd_section_open"] = not st.session_state["usd_fwd_section_open"]

            if st.session_state["usd_fwd_section_open"]:
                _usd_fwd_cols = st.columns([2, 2, 2])
                with _usd_fwd_cols[0]:
                    _usd_fwd_mode = st.radio(
                        "Curve", ["SOFR OIS", "FF OIS", "SOFR-FF Basis"],
                        horizontal=True, key="usd_fwd_mode"
                    )
                with _usd_fwd_cols[1]:
                    _gen_usd_fwd = st.button("▶ Generate USD Forward Matrix", key="gen_usd_fwd", type="primary", use_container_width=True)
                with _usd_fwd_cols[2]:
                    _has_usd_fwd = "SOFR OIS" in st.session_state.get("usd_fwd_matrix", {})
                    st.download_button("⬇ Download",
                        data=st.session_state["usd_fwd_matrix"].get(_usd_fwd_mode, pd.DataFrame()).to_csv() if _has_usd_fwd else "",
                        file_name=f"USD_fwd_{_usd_fwd_mode.replace(' ','_')}.csv",
                        key="dl_usd_fwd", use_container_width=True, disabled=not _has_usd_fwd)

                if _gen_usd_fwd:
                    st.session_state["_gen_usd_fwd_requested"] = True

                if st.session_state.get("_gen_usd_fwd_requested"):
                    st.session_state.pop("_gen_usd_fwd_requested", None)

                    # Standard USD expiries and tenors
                    # Match AUD expiry grid exactly (22 rows)
                    _USD_EXPIRIES = [1/52, 1/12, 2/12, 3/12, 6/12, 9/12, 1, 1.5, 2, 3, 4, 5, 6, 7, 8, 9, 10, 12, 15, 20, 25, 30]
                    _USD_TENORS   = [1, 2, 3, 4, 5, 7, 10, 12, 15, 20, 25, 30]
                    _EXP_LABELS   = ["1w","1m","2m","3m","6m","9m","1y","18m","2y","3y","4y","5y","6y","7y","8y","9y","10y","12y","15y","20y","25y","30y"]
                    _TEN_LABELS   = ["1Y","2Y","3Y","4Y","5Y","7Y","10Y","12Y","15Y","20Y","25Y","30Y"]

                    def _interp_rate(df_curve, maturity, col="ZeroRatePct"):
                        """Linear interpolation from a zero curve DataFrame."""
                        xs = df_curve["MaturityY"].values
                        ys = df_curve[col].values
                        return float(np.interp(maturity, xs, ys))

                    def _usd_fwd_rate(df_curve, exp, ten, col="ZeroRatePct"):
                        """Forward rate from zero curve: (z2*t2 - z1*t1) / tenor."""
                        if df_curve is None or df_curve.empty: return None
                        t1, t2 = exp, exp + ten
                        z1 = _interp_rate(df_curve, t1, col) / 100
                        z2 = _interp_rate(df_curve, t2, col) / 100
                        return round(((z2 * t2 - z1 * t1) / ten) * 100, 4)

                    with st.spinner("Generating USD forward matrices..."):
                        # SOFR forward matrix
                        _sofr_rows = {}
                        for ei, exp in enumerate(_USD_EXPIRIES):
                            _row = {}
                            for ti, ten in enumerate(_USD_TENORS):
                                _row[_TEN_LABELS[ti]] = _usd_fwd_rate(_sofr_curve, exp, ten)
                            _sofr_rows[_EXP_LABELS[ei]] = _row
                        _sofr_df = pd.DataFrame(_sofr_rows).T
                        _sofr_df.index.name = "Expiry"
                        _sofr_df = _sofr_df.reset_index()

                        # FF OIS forward matrix
                        _ff_rows = {}
                        for ei, exp in enumerate(_USD_EXPIRIES):
                            _row = {}
                            for ti, ten in enumerate(_USD_TENORS):
                                _row[_TEN_LABELS[ti]] = _usd_fwd_rate(_ff_ois, exp, ten) if _ff_ois is not None else None
                            _ff_rows[_EXP_LABELS[ei]] = _row
                        _ff_df = pd.DataFrame(_ff_rows).T
                        _ff_df.index.name = "Expiry"
                        _ff_df = _ff_df.reset_index()

                        # SOFR-FF Basis forward matrix (bp, interpolated directly)
                        _bas_rows = {}
                        for ei, exp in enumerate(_USD_EXPIRIES):
                            _row = {}
                            for ti, ten in enumerate(_USD_TENORS):
                                if _sofr_ff_bas is not None and not _sofr_ff_bas.empty:
                                    _mid = float(np.interp(exp + ten/2,
                                                           _sofr_ff_bas["MaturityY"].values,
                                                           _sofr_ff_bas["BasisBp"].values))
                                    _row[_TEN_LABELS[ti]] = round(_mid, 2)
                                else:
                                    _row[_TEN_LABELS[ti]] = None
                            _bas_rows[_EXP_LABELS[ei]] = _row
                        _bas_df = pd.DataFrame(_bas_rows).T
                        _bas_df.index.name = "Expiry"
                        _bas_df = _bas_df.reset_index()

                        st.session_state["usd_fwd_matrix"]["SOFR OIS"]       = _sofr_df
                        st.session_state["usd_fwd_matrix"]["FF OIS"]          = _ff_df
                        st.session_state["usd_fwd_matrix"]["SOFR-FF Basis"]   = _bas_df

                # Display selected matrix
                _disp_key = _usd_fwd_mode
                _disp_df  = st.session_state.get("usd_fwd_matrix", {}).get(_disp_key)
                if _disp_df is not None and not _disp_df.empty:
                    _num_cols = [c for c in _disp_df.columns if c != "Expiry"]
                    _fmt_dict = {c: "{:.4f}" for c in _num_cols}
                    st.dataframe(
                        _disp_df.style.format(_fmt_dict).background_gradient(
                            cmap="RdYlGn_r" if _disp_key == "SOFR-FF Basis" else "RdYlGn",
                            subset=_num_cols),
                        use_container_width=True, hide_index=True, height=820
                    )
                else:
                    st.info("Click **▶ Generate USD Forward Matrix** to compute.")


    # ── Chart toggles (AUD/NZD only) ─────────────────────────────────────────
    # AUD/NZD chart — defaults so USD path through try block is harmless
    _show_par = _show_irs = _show_ois = _show_b6 = _show_b3 = False
    if ccy != "USD":
        _ck = st.columns(5)
        with _ck[0]: _show_par = st.checkbox("IRS Par", value=True, key="chart_par")
        with _ck[1]: _show_irs = st.checkbox("IRS Zero", value=True, key="chart_irs")
        with _ck[2]: _show_ois = st.checkbox("OIS", value=True, key="chart_ois")
        with _ck[3]: _show_b6  = st.checkbox("6v3 Basis", value=True, key="chart_b6")
        with _ck[4]: _show_b3  = st.checkbox("3v1 Basis", value=True, key="chart_b3")

    if ccy != "USD":
     try:
        fig = go.Figure()
        if _show_par:
            if par_rates is not None and not par_rates.empty:
                try:
                    _par_x = list(par_rates["Tenor"].apply(
                        lambda x: float(x[:-1]) if str(x).endswith("Y") else float(str(x)[:-1])/12))
                    _par_y = list(par_rates["Par Rate (%)"])
                    # Add 40Y/50Y from Curves_AUD only if genuinely absent — normalise float comparison
                    for _, _cr in curve_c.iterrows():
                        _m = float(_cr["MaturityY"])
                        if _m in [40.0, 50.0] and not any(abs(_m - _px) < 0.01 for _px in _par_x):
                            _par_x.append(_m); _par_y.append(float(_cr["ZeroRatePct"]))
                    _ext_pairs = sorted(zip(_par_x, _par_y))
                    fig.add_trace(go.Scatter(
                        x=[p[0] for p in _ext_pairs],
                        y=[p[1] for p in _ext_pairs],
                        mode="lines+markers", name="IRS Par", line=dict(color="#22c55e", width=2)))
                except Exception:
                    pass
            else:
                fig.add_trace(go.Scatter(x=curve_c["MaturityY"], y=curve_c["ZeroRatePct"],
                    mode="lines+markers", name="IRS Par", line=dict(color="#22c55e", width=2)))
        if _show_irs:
            # Display bootstrapped zeros from _aud_proj_curve, extended to 40/50Y from _aud_zc_ss
            if ccy == "AUD" and st.session_state.get("_aud_proj_curve") is not None:
                _proj = st.session_state["_aud_proj_curve"]
                _zx = list(_proj["MaturityY"].astype(float))
                _zy = list(_proj["ZeroRatePct"].astype(float))
                # Extend to 40Y/50Y using bootstrapped SS zeros — NOT curve_c which holds par rates
                _zc_ss_ext = st.session_state.get("_aud_zc_ss") or {}
                for _et in [40.0, 50.0]:
                    if _et in _zc_ss_ext and not any(abs(_et - _zxi) < 0.01 for _zxi in _zx):
                        _zx.append(_et); _zy.append(round(float(_zc_ss_ext[_et]), 4))
            else:
                _zx = list(curve_c["MaturityY"].astype(float))
                _zy = list(curve_c["ZeroRatePct"].astype(float))
            _pairs = sorted(zip(_zx, _zy))
            fig.add_trace(go.Scatter(
                x=[p[0] for p in _pairs], y=[p[1] for p in _pairs],
                mode="lines+markers", name="IRS Zero", line=dict(color="#3b82f6", width=2)))
        if _show_ois and oisc is not None and not oisc.empty:
            fig.add_trace(go.Scatter(x=oisc["MaturityY"], y=oisc["ZeroRatePct"],
                mode="lines+markers", name="OIS", line=dict(color="#f59e0b", width=2)))
        if _show_b6 and b6c is not None and not b6c.empty:
            fig.add_trace(go.Scatter(x=b6c["MaturityY"], y=b6c["BasisBp"],
                mode="lines+markers", name="6v3 Basis (bp)",
                yaxis="y2", line=dict(color="#ef4444", width=2, dash="dot")))
        if _show_b3 and b3c is not None and not b3c.empty:
            fig.add_trace(go.Scatter(x=b3c["MaturityY"], y=b3c["BasisBp"],
                mode="lines+markers", name="3v1 Basis (bp)",
                yaxis="y2", line=dict(color="#a855f7", width=2, dash="dot")))
        fig.update_layout(height=380, template="plotly_dark",
            xaxis=dict(title="Maturity (Years)"),
            yaxis=dict(title="Rate (%)"),
            yaxis2=dict(title="Basis (bp)", overlaying="y", side="right", showgrid=False),
            legend=dict(orientation="h", y=1.1),
            margin=dict(l=40, r=40, t=20, b=40))
        st.plotly_chart(fig, use_container_width=True)
     except Exception as _e:
        st.warning(f"Chart: {_e}")

    if ccy != "USD":
     with st.expander("IRS Par Rates & Curve Data", expanded=False):
        _cols_to_show = []
        if ccy == "USD": pass  # no AUD data tables for USD
        elif _show_par:
            if par_rates is not None and not par_rates.empty:
                import pandas as _pd2
                # Normalise tenor labels: "40.0Y" → "40Y", "50.0Y" → "50Y"
                _par_table = par_rates.copy()
                _par_table["Tenor"] = _par_table["Tenor"].astype(str).str.replace(r"^(\d+)\.0Y$", lambda m: f"{int(m.group(1))}Y", regex=True)
            else:
                _par_table = curve_c
            _cols_to_show.append(("IRS Par Rates (%)", _par_table))
        if _show_irs:
            if ccy == "AUD" and st.session_state.get("_aud_proj_curve") is not None:
                _proj_disp = st.session_state["_aud_proj_curve"].copy()
                # Extend to 40/50Y using bootstrapped SS zeros — NOT curve_c which holds par rates
                import pandas as _pd2
                _existing_m = set(_proj_disp["MaturityY"].astype(float).tolist())
                _zc_ss_tbl = st.session_state.get("_aud_zc_ss") or {}
                _extra = []
                for _et in [40.0, 50.0]:
                    if _et not in _existing_m:
                        if _et in _zc_ss_tbl:
                            _extra.append({"MaturityY": _et, "ZeroRatePct": round(float(_zc_ss_tbl[_et]), 4)})
                if _extra:
                    _proj_disp = _pd2.concat([_proj_disp, _pd2.DataFrame(_extra)], ignore_index=True)
                _cols_to_show.append(("IRS Zero Curve (%)", _proj_disp))
            else:
                _cols_to_show.append(("IRS Zero Curve (%)", curve_c))
        if _show_ois and oisc is not None and not oisc.empty:
            _cols_to_show.append(("OIS Curve (%)", oisc))
        if _show_b6 and b6c is not None and not b6c.empty:
            _cols_to_show.append(("6v3 Basis (bp)", b6c))
        if _show_b3 and b3c is not None and not b3c.empty:
            _cols_to_show.append(("3v1 Basis (bp)", b3c))
        if not _cols_to_show:
            _par_table = par_rates if (par_rates is not None and not par_rates.empty) else curve_c
            _cols_to_show.append(("IRS Par Rates (%)", _par_table))
        _tcols = st.columns(len(_cols_to_show))
        for _i, (_label, _df) in enumerate(_cols_to_show):
            with _tcols[_i]:
                st.caption(_label)
                st.dataframe(_df, use_container_width=True, hide_index=True)

    # ── IRS Forward Matrix (AUD/NZD only) ────────────────────────────────────────
    if ccy != "USD":
        if "fwd_matrix"   not in st.session_state: st.session_state["fwd_matrix"]   = {}
        if "basis_matrix" not in st.session_state: st.session_state["basis_matrix"] = {}
        if "fwd_section_open" not in st.session_state: st.session_state["fwd_section_open"] = True
        st.markdown("---")

        has_fwd = ccy in st.session_state.get("fwd_matrix", {}) and \
                  not st.session_state["fwd_matrix"][ccy].empty

        _fl = "▼ Hide Forward Swap Rates" if st.session_state["fwd_section_open"] else "▶ Show Forward Swap Rates"
        if st.button(_fl, key="fwd_toggle"):
            st.session_state["fwd_section_open"] = not st.session_state["fwd_section_open"]
            st.rerun()

        if st.session_state["fwd_section_open"]:
            _r1, _r2, _r3, _r4 = st.columns([3, 1, 3, 3])
        with _r1:
            leg_conv = st.radio("Leg Convention", ["Market","Q/Q","S/S"],
                                horizontal=True, key="fwd_leg_convention")
        with _r2:
            show_hm = st.checkbox("Heatmap", value=False, key="show_heatmap")
        with _r3:
            gen_fwd = st.button("▶ Generate Forward Matrix", key="gen_fwd_matrix",
                                type="primary", use_container_width=True,
                                help="Force regenerate. Convention changes auto-update below.")
        with _r4:
            st.download_button("⬇ Download",
                               st.session_state["fwd_matrix"][ccy].to_csv() if has_fwd else "",
                               f"{ccy}_fwd_matrix.csv", key="dl_fwd",
                               use_container_width=True, type="primary",
                               disabled=not has_fwd)

        _mc = st.session_state.get("config_curves", {}).get(ccy)
        _mb = st.session_state.get("config_basis", {}).get(ccy, {}).get("6v3")
        _conv_now = {"Market":"market","Q/Q":"qq","S/S":"ss"}.get(leg_conv,"market")
        _prev_conv = st.session_state.get("fwd_convention", "market")
        # Auto-regen on convention change; CCY change requires explicit button press
        _need_regen = gen_fwd or _conv_now != _prev_conv

        _mb3v1 = st.session_state.get("config_basis", {}).get(ccy, {}).get("3v1")
        if _need_regen and _mc is not None:
            with st.spinner("Calculating..."):
                fm = generate_forward_matrix_convention(ccy, _mc, _mb, _conv_now)
                st.session_state["fwd_matrix"][ccy] = fm
                st.session_state["fwd_convention"]  = _conv_now
                if _mb is not None:
                    st.session_state["basis_matrix"][ccy] = generate_basis_matrix(ccy, _mb)
                # 3v1 basis inside spinner so UI does not freeze after main matrix
                if _mb3v1 is not None:
                    if "basis_matrix_3v1" not in st.session_state:
                        st.session_state["basis_matrix_3v1"] = {}
                    st.session_state["basis_matrix_3v1"][ccy] = generate_basis_matrix(ccy, _mb3v1)
            has_fwd = True
        elif _need_regen and _mc is None:
            st.error("No curve — upload config first")

        if has_fwd:
            has_basis   = ccy in st.session_state.get("basis_matrix", {})
            has_basis3v1 = ccy in st.session_state.get("basis_matrix_3v1", {})
            _vo = ["IRS Fwd"]
            if has_basis:    _vo.append("6v3 Basis")
            if has_basis3v1: _vo.append("3v1 Basis")
            _rv = st.radio("View", _vo, horizontal=True, key="rate_view_toggle")
            if _rv == "IRS Fwd":
                _disp = st.session_state["fwd_matrix"][ccy]
            elif _rv == "6v3 Basis":
                _disp = st.session_state["basis_matrix"].get(ccy)
            else:
                _disp = st.session_state.get("basis_matrix_3v1", {}).get(ccy)
            if _disp is not None:
                _nc  = [c for c in _disp.columns if c != "Expiry"]
                _safe_fmt = lambda x: f"{x:.4f}" if isinstance(x, (int, float)) and x == x else ""
                _fmt = {c: _safe_fmt for c in _nc}
                if show_hm:
                    _cm = "RdYlGn_r" if _rv == "IRS Fwd" else "RdYlGn"
                    st.dataframe(_disp.style.format(_fmt).background_gradient(_cm, axis=None, subset=_nc),
                                 use_container_width=True, height=820)
                else:
                    st.dataframe(_disp.style.format(_fmt), use_container_width=True, height=820)
        else:
            st.info("Click **▶ Generate Forward Matrix**")


    # ── 📡 Publish to Options Whiteboard ──────────────────────────────────────────────────
    st.markdown("---")
    _pb1, _pb2 = st.columns([2, 4])
    with _pb1:
        if st.button("📡 Publish ATM Vols / Prems / FWDs to Options Whiteboard", disabled=is_trainee(),
                     key="curves_publish_blotter", type="primary",
                     use_container_width=True):
            if not HAS_POSTGRES:
                st.error("Database not connected.")
            elif not is_admin():
                st.warning("Admin only.")
            else:
                _pub_ccy = ccy
                _all_mids = {}
                # ATM Vol mids
                _atm_s = get_working_atm_surface(_pub_ccy)
                if _atm_s is not None:
                    _av = _atm_s.copy()
